@HiltViewModel
class ThermalAnomalyViewModel @Inject constructor(
    @ApplicationContext private val context: android.content.Context,
    private val plantRepository: PlantRepository,
    private val equipmentRepository: EquipmentRepository,
    private val equipmentComponentRepository: EquipmentComponentRepository,
    private val recordRepository: ThermographicInspectionRecordRepository,
    private val inspectionRecordRepository: InspectionRecordRepository,
    private val flirReader: FlirThermogramReader,
    private val thermogramRepository: ThermogramRepository,
    private val limitsRepository: EquipmentComponentTemperatureLimitsRepository,
    private val riskRepo: RiskPeriodicityDeadlineRepository,
    private val userInfoRepository: UserInfoRepository,
    private val roiRepository: ROIRepository,
    private val sessionStore: UserSessionStore,
    private val flirNetworkService: FlirNetworkService
) : ViewModel() {

    // ── Estado do monitoramento FLIR em background ────────────────────────────
    /** true quando a câmera FLIR de rede está monitorando e importando termogramas */
    val flirMonitoringActive: StateFlow<Boolean> = flirNetworkService.monitoringActive

    /** Caminho local do último termograma importado da câmera FLIR de rede */
    val flirLastImportedFile: StateFlow<String?> = flirNetworkService.lastImportedFile

    /** Nome/modelo da câmera FLIR conectada, ou null se não conectada */
    val flirConnectedCameraName: StateFlow<String?> = flirNetworkService.connectionState
        .map { state -> if (state is CameraConnectionState.Connected) state.deviceId else null }
        .stateIn(viewModelScope, SharingStarted.Eagerly, null)
    // ─────────────────────────────────────────────────────────────────────────

    private val _uiState = MutableStateFlow(ThermalAnomalyUiState())
    val uiState: StateFlow<ThermalAnomalyUiState> = _uiState.asStateFlow()

    private val plants: StateFlow<List<PlantEntity>> = plantRepository.getAllPlants()
        .stateIn(viewModelScope, SharingStarted.Lazily, emptyList())

    init {
        // Initialize plants in UI state
        viewModelScope.launch {
            plants.collect { allPlants ->
                _uiState.update { it.copy(availablePlants = allPlants) }
            }
        }
    }

    fun onEvent(event: ThermalAnomalyEvent) {
        when (event) {
            is ThermalAnomalyEvent.InitializeForm -> {
                // Processamento SEQUENCIAL dentro de uma única coroutine:
                // planta → equipamento → roteiro.
                // Cada passo só inicia após o anterior terminar, eliminando a race condition
                // que ocorria quando o IO estava saturado (ex: câmera FLIR monitorando).
                viewModelScope.launch {
                    // 1. Planta — seta sem resetar equipamento (passo 2 vai defini-lo logo abaixo)
                    event.plantId?.let { id ->
                        try {
                            val plant = plantRepository.getPlantById(id)
                            if (plant != null) {
                                _uiState.update { it.copy(selectedPlant = plant) }
                                // Lista de equipamentos para o dropdown — fire-and-forget
                                launch {
                                    equipmentRepository.getEquipmentsByPlantId(plant.id)
                                        .collect { list -> _uiState.update { it.copy(filteredEquipments = list) } }
                                }
                            }
                        } catch (e: Exception) {
                            Log.w("ThermAnomVM", "InitializeForm plant failed: ${e.message}")
                        }
                    }

                    // 2. Equipamento (executa somente após o passo 1 completar)
                    event.equipmentId?.let { id ->
                        try {
                            val equipment = equipmentRepository.getEquipmentById(id)
                            if (equipment != null) handleEquipmentSelected(equipment)
                        } catch (e: Exception) {
                            Log.w("ThermAnomVM", "InitializeForm equipment failed: ${e.message}")
                        }
                    }

                    // 3. Roteiro de inspeção (executa somente após o passo 2 completar)
                    event.inspectionRecordId?.let { id ->
                        try {
                            val record = inspectionRecordRepository.getInspectionRecordById(id)
                            if (record != null) _uiState.update { it.copy(selectedInspectionRecord = record) }
                        } catch (e: Exception) {
                            Log.w("ThermAnomVM", "InitializeForm inspection failed: ${e.message}")
                        }
                    }
                }
            }
            is ThermalAnomalyEvent.PlantSelectedById -> {
                viewModelScope.launch {
                    try {
                        val plant = plantRepository.getPlantById(event.plantId)
                        // resetEquipment = false: fallback de segurança caso seja chamado
                        // fora do fluxo InitializeForm
                        if (plant != null) handlePlantSelected(plant, resetEquipment = false)
                    } catch (e: Exception) {
                        Log.w("ThermAnomVM", "PlantSelectedById failed: ${e.message}")
                    }
                }
            }
            is ThermalAnomalyEvent.EquipmentSelectedById -> {
                viewModelScope.launch {
                    try {
                        val equipment = equipmentRepository.getEquipmentById(event.equipmentId)
                        if (equipment != null) handleEquipmentSelected(equipment)
                    } catch (e: Exception) {
                        Log.w("ThermAnomVM", "EquipmentSelectedById failed: ${e.message}")
                    }
                }
            }
            is ThermalAnomalyEvent.InspectionRecordSelectedById -> {
                viewModelScope.launch {
                    try {
                        val record = inspectionRecordRepository.getInspectionRecordById(event.recordId)
                        if (record != null) _uiState.update { it.copy(selectedInspectionRecord = record) }
                    } catch (e: Exception) {
                        Log.w("ThermAnomVM", "InspectionRecordSelectedById failed: ${e.message}")
                    }
                }
            }
            is ThermalAnomalyEvent.PlantSelected -> handlePlantSelected(event.plant).also { _uiState.update { it.copy(isDirty = true) } }
            is ThermalAnomalyEvent.EquipmentSelected -> handleEquipmentSelected(event.equipment).also { _uiState.update { it.copy(isDirty = true) } }
            is ThermalAnomalyEvent.ComponentSelected -> handleComponentSelected(event.component).also { _uiState.update { it.copy(isDirty = true) } }
            is ThermalAnomalyEvent.UpdateRecordName -> _uiState.update { it.copy(recordName = event.value, isDirty = true) }
            is ThermalAnomalyEvent.UpdateServiceOrder -> _uiState.update { it.copy(serviceOrder = event.value, isDirty = true) }
            is ThermalAnomalyEvent.UpdateAnalysis -> _uiState.update { it.copy(analysisDescription = event.value, isDirty = true) }
            is ThermalAnomalyEvent.UpdateCondition -> {
                _uiState.update { it.copy(condition = event.value, isDirty = true) }
                viewModelScope.launch {
                    _uiState.value.selectedPlant?.let { p ->
                        val anomalyRecords = recordRepository.getThermographicInspectionRecordsByPlantId(p.id).first()
                        setThermalRecordName(p, event.value, anomalyRecords)
                    }
                    applyRiskPeriodicity(event.value)
                    // Atualiza recomendações e descrição de análise somente após aplicar a periodicidade/condição
                    updateAnalysisAndRecommendations()
                }
            }
            is ThermalAnomalyEvent.UpdateDeadline -> {
                _uiState.update { it.copy(deadlineExecution = event.value, isDirty = true) }
            }
            is ThermalAnomalyEvent.UpdateNextMonitoring -> {
                _uiState.update { it.copy(nextMonitoring = event.value, isDirty = true) }
            }
            is ThermalAnomalyEvent.UpdateRecommendations -> _uiState.update { it.copy(recommendations = event.value, isDirty = true) }
            is ThermalAnomalyEvent.InspectionRecordSelected -> _uiState.update { it.copy(selectedInspectionRecord = event.record, isDirty = true) }
            is ThermalAnomalyEvent.ThermographicSelectedById -> {
                viewModelScope.launch {
                    try {
                        val therm = recordRepository.getThermographicInspectionRecordById(event.thermographicId)
                        if (therm != null) {
                            val plant = therm.plantId.let { plantRepository.getPlantById(it) }
                            val equipment = therm.equipmentId.let { equipmentRepository.getEquipmentById(it) }
                            val inspectionRecord = therm.routeId?.let { inspectionRecordRepository.getInspectionRecordById(it) }
                            val component = therm.componentId?.let { equipmentComponentRepository.getEquipmentComponentById(it) }

                            var loadedThermogram: com.tech.thermography.android.data.local.entity.ThermogramEntity? = null
                            var loadedRois: List<com.tech.thermography.android.data.local.entity.ROIEntity> = emptyList()
                            var loadedThermogramRef: com.tech.thermography.android.data.local.entity.ThermogramEntity? = null
                            var loadedRoisRef: List<com.tech.thermography.android.data.local.entity.ROIEntity> = emptyList()

                            try {
                                loadedThermogram = thermogramRepository.getThermogramById(therm.thermogramId)
                                if (loadedThermogram != null) {
                                    loadedRois = roiRepository.getRoisByThermogramId(loadedThermogram.id).first()
                                }

                                therm.thermogramRefId?.let { refId ->
                                    loadedThermogramRef = thermogramRepository.getThermogramById(refId)
                                    if (loadedThermogramRef != null) {
                                        loadedRoisRef = roiRepository.getRoisByThermogramId(loadedThermogramRef!!.id).first()
                                    }
                                }
                            } catch (e: Exception) {
                                Log.w("ThermAnomVM", "Failed to load thermogram or rois: ${e.message}")
                            }

                            _uiState.update { state ->
                                state.copy(
                                    selectedPlant = plant ?: state.selectedPlant,
                                    selectedEquipment = equipment ?: state.selectedEquipment,
                                    selectedComponent = component ?: state.selectedComponent,
                                    selectedInspectionRecord = inspectionRecord ?: state.selectedInspectionRecord,
                                    recordName = therm.name,
                                    serviceOrder = therm.serviceOrder ?: "",
                                    analysisDescription = therm.analysisDescription ?: "",
                                    condition = therm.condition,
                                    recommendations = therm.recommendations ?: "",
                                    deadlineExecution = therm.deadlineExecution?.atStartOfDay(ZoneId.systemDefault())?.toInstant()?.toEpochMilli(),
                                    nextMonitoring = therm.nextMonitoring?.atStartOfDay(ZoneId.systemDefault())?.toInstant()?.toEpochMilli(),
                                    isEditing = true,
                                    thermogramId = therm.id,
                                    thermogram = loadedThermogram ?: state.thermogram,
                                    thermogramRois = loadedRois.ifEmpty { state.thermogramRois },
                                    selectedRoi = loadedRois.find { it.id == loadedThermogram?.selectedRoiId } ?: loadedRois.firstOrNull(),

                                    thermogramRef = loadedThermogramRef ?: state.thermogramRef,
                                    thermogramRefRois = loadedRoisRef.ifEmpty { state.thermogramRefRois },
                                    selectedRefRoi = loadedRoisRef.find { it.id == loadedThermogramRef?.selectedRoiId } ?: loadedRoisRef.firstOrNull(),

                                    thermogramImageUri = loadedThermogram?.localImagePath?.takeIf { it.isNotBlank() }?.toUri() ?: state.thermogramImageUri,
                                    // Preenche a imagem real (localImageRefPath) a partir do thermogram, se disponível
                                    realImageUri = loadedThermogram?.localImageRefPath?.takeIf { it.isNotBlank() }?.let { path ->
                                        when {
                                            path.startsWith("content://") -> android.net.Uri.parse(path)
                                            path.startsWith("file://") -> android.net.Uri.parse(path)
                                            else -> java.io.File(path).toUri()
                                        }
                                    } ?: state.realImageUri,
                                    // Preenche a imagem de referência a partir do thermogramRef local path
                                    thermogramRefImageUri = loadedThermogramRef?.localImagePath?.takeIf { it.isNotBlank() }?.toUri() ?: state.thermogramRefImageUri
                                )
                            }
                        }
                    } catch (e: Exception) {
                        Log.w("ThermAnomVM", "Failed to load thermographic by id: ${e.message}")
                    }
                }
            }

            is ThermalAnomalyEvent.SelectRoi -> handleRoiSelected(event.roi).also { _uiState.update { it.copy(isDirty = true) } }
            is ThermalAnomalyEvent.SelectRefRoi -> handleRefRoiSelected(event.roi).also { _uiState.update { it.copy(isDirty = true) } }
            is ThermalAnomalyEvent.UpdateThermogramImage -> handleImageSelected(event.uri).also { _uiState.update { it.copy(isDirty = true) } }
            is ThermalAnomalyEvent.UpdateRefThermogramImage -> handleRefImageSelected(event.uri).also { _uiState.update { it.copy(isDirty = true) } }
            is ThermalAnomalyEvent.UpdateRealImage -> handleRealImageSelected(event.uri).also { _uiState.update { it.copy(isDirty = true) } }

            ThermalAnomalyEvent.Save -> saveRecord()
            ThermalAnomalyEvent.Cancel -> resetForm()
        }
    }

    private fun handlePlantSelected(plant: PlantEntity, resetEquipment: Boolean = true) {
        _uiState.update { it.copy(
            selectedPlant = plant,
            selectedEquipment = if (resetEquipment) null else it.selectedEquipment,
            filteredInspectionRecords = if (resetEquipment) emptyList() else it.filteredInspectionRecords,
            equipmentType = if (resetEquipment) "" else it.equipmentType
        ) }
        viewModelScope.launch {
            equipmentRepository.getEquipmentsByPlantId(plant.id).collect { equipmentList ->
                _uiState.update { it.copy(filteredEquipments = equipmentList) }
            }
            val anomalyRecords = recordRepository.getThermographicInspectionRecordsByPlantId(plant.id).first()
            val condition = _uiState.value.condition
            val currentState = _uiState.value
            if (!currentState.isEditing && currentState.recordName.isBlank()) {
                val n = anomalyRecords.size
                val numberPart = String.format(Locale.US, "%03d", n + 1)
                val codePart = plant.code ?: plant.name ?: plant.id.toString()
                val generated = "CAT_${numberPart}_$codePart"
                _uiState.update { it.copy(recordName = generated) }
            } else {
                setThermalRecordName(plant, condition, anomalyRecords)
            }
        }
    }

    private fun handleEquipmentSelected(equipment: EquipmentEntity) {
        _uiState.update { it.copy(
            selectedEquipment = equipment,
            equipmentType = generateEquipmentTypeString(equipment),
            selectedComponent = null
        ) }
        viewModelScope.launch {
            val inspectionRecords = inspectionRecordRepository.getInspectionRecordsByEquipmentId(equipment.id)
            _uiState.update { it.copy(filteredInspectionRecords = inspectionRecords) }
            val componentCode = getEquipmentComponentCode(equipment.type)
            val allComponents = equipmentComponentRepository.getAllEquipmentComponents().first()
            val filteredComponents = if (componentCode.isNotEmpty()) {
                allComponents.filter { it.code == componentCode }
            } else {
                emptyList()
            }
            _uiState.update { it.copy(availableComponents = filteredComponents) }
            updateAnalysisAndRecommendations()
        }
    }

    private fun getEquipmentComponentCode(equipmentType: EquipmentType): String {
        return when (equipmentType) {
            EquipmentType.AUTOTRANSFORMER -> "TF"
            EquipmentType.POWER_TRANSFORMER -> "TF"
            EquipmentType.SHUNT_REACTOR -> "TF"
            EquipmentType.CURRENT_TRANSFORMER -> "TC"
            EquipmentType.POTENTIAL_TRANSFORMER -> "TP"
            EquipmentType.CIRCUIT_BREAKER -> "DJ"
            EquipmentType.DISCONNECT_SWITCH -> "SC"
            EquipmentType.SURGE_ARRESTER -> "PR"
            EquipmentType.CAPACITOR_BANK -> "CA"
            EquipmentType.BATTERY_BANK -> "BT"
            EquipmentType.ELECTRICAL_PANEL -> "PA"
            EquipmentType.PROTECTION_CONTROL_PANEL -> "PA"
            EquipmentType.METAL_CLAD_SWITCHGEAR -> "CB"
            else -> ""
        }
    }

    private fun generateEquipmentTypeString(equipment: EquipmentEntity): String {
        val code = equipment.code?.takeIf { it.isNotBlank() }
        return if (code != null) "$code (${equipment.name})" else equipment.name
    }

    private fun saveRecord() {
        val state = _uiState.value

        if (state.selectedPlant == null || state.selectedEquipment == null) {
            _uiState.update { it.copy(error = "Por favor, selecione Instalação e Equipamento") }
            return
        }

        if (state.isEditing && state.recordName.isBlank()) {
            _uiState.update { it.copy(error = "Por favor, preencha o nome do relatório para edição") }
            return
        }

        var finalRecordName = state.recordName

        viewModelScope.launch {
            try {
                val current = _uiState.value
                val plant = current.selectedPlant ?: state.selectedPlant

                if (!current.isEditing && finalRecordName.isBlank()) {
                    val existing = recordRepository.getThermographicInspectionRecordsByPlantId(plant.id).first()
                    val n = existing.size
                    val numberPart = String.format(Locale.US, "%03d", n + 1)
                    val codePart = plant.code ?: plant.name ?: plant.id.toString()
                    finalRecordName = "CAT_${numberPart}_$codePart"
                    _uiState.update { it.copy(recordName = finalRecordName) }
                }

                _uiState.update { it.copy(isLoading = true, error = null) }
                val conditionType = current.condition
                val createdById = resolveCurrentUserId()

                // 1. Persistir o termograma principal (Monitoramento)
                val thermId: UUID = current.thermogram?.let { t ->
                    val toInsert = t.copy(
                        createdById = createdById,
                        selectedRoiId = current.selectedRoi?.id,
                        maxTempRoi = current.selectedRoi?.maxTemp
                    )
                    if (thermogramRepository.getThermogramById(toInsert.id) != null) {
                        thermogramRepository.updateThermogram(toInsert)
                    } else {
                        thermogramRepository.insertThermogram(toInsert)
                    }

                    // Salvar ROIs associadas al monitoramento
                    val roiEntities = current.thermogramRois.map { roi -> roi.copy(thermogramId = toInsert.id) }
                    roiRepository.insertROIs(roiEntities)

                    toInsert.id
                } ?: UUID.randomUUID()

                // 2. Persistir o termograma de referência
                val thermRefId: UUID? = current.thermogramRef?.let { tRef ->
                    val toInsertRef = tRef.copy(
                        createdById = createdById,
                        selectedRoiId = current.selectedRefRoi?.id,
                        maxTempRoi = current.selectedRefRoi?.maxTemp
                    )
                    if (thermogramRepository.getThermogramById(toInsertRef.id) != null) {
                        thermogramRepository.updateThermogram(toInsertRef)
                    } else {
                        thermogramRepository.insertThermogram(toInsertRef)
                    }

                    // Salvar ROIs associadas à referência (garantindo o vínculo com o thermogramRef)
                    val roiEntitiesRef = current.thermogramRefRois.map { roi -> roi.copy(thermogramId = toInsertRef.id) }
                    roiRepository.insertROIs(roiEntitiesRef)

                    toInsertRef.id
                }

                val deltaT = calculateTemperatureDifference() ?: 0.0

                val record = ThermographicInspectionRecordEntity(
                    id = if (current.isEditing) current.thermogramId ?: UUID.randomUUID() else UUID.randomUUID(),
                    name = finalRecordName,
                    type = ThermographicInspectionRecordType.ANOMALY_INITIAL,
                    serviceOrder = state.serviceOrder.ifBlank { null },
                    createdAt = Instant.now(),
                    analysisDescription = state.analysisDescription.ifBlank { null },
                    condition = conditionType,
                    deltaT = deltaT,
                    periodicity = null,
                    deadlineExecution = state.deadlineExecution?.let { Instant.ofEpochMilli(it).atZone(ZoneId.systemDefault()).toLocalDate() },
                    nextMonitoring = state.nextMonitoring?.let { Instant.ofEpochMilli(it).atZone(ZoneId.systemDefault()).toLocalDate() },
                    recommendations = state.recommendations.ifBlank { null },
                    finished = false,
                    finishedAt = null,
                    plantId = requireNotNull(state.selectedPlant).id,
                    routeId = state.selectedInspectionRecord?.id,
                    equipmentId = requireNotNull(state.selectedEquipment).id,
                    componentId = state.selectedComponent?.id,
                    createdById = createdById,
                    finishedById = createdById,
                    thermogramId = thermId,
                    thermogramRefId = thermRefId,
                    syncStatus = RecordSyncStatus.NEW
                )

                if (current.isEditing) {
                    val existingRecords = recordRepository.getThermographicInspectionRecordsByPlantId(plant.id).first()
                    val original = existingRecords.find { it.name == finalRecordName }
                    val recordToSave = if (original != null) record.copy(id = original.id, syncStatus = RecordSyncStatus.EDITED) else record
                    recordRepository.updateThermographicInspectionRecord(context, recordToSave)
                } else {
                    recordRepository.insertThermographicInspectionRecord(context, record)
                }

                _uiState.update { it.copy(isLoading = false, isSaved = true, error = null) }
            } catch (e: Exception) {
                _uiState.update { it.copy(isLoading = false, error = e.message ?: "Erro ao salvar registro") }
            }
        }
    }

    private fun resetForm() {
        _uiState.update {
            ThermalAnomalyUiState(
                availablePlants = it.availablePlants,
                filteredEquipments = emptyList()
            )
        }
    }

    fun setThermalRecordName(powerStation: PlantEntity?, condition: ConditionType, anomalyRecords: List<ThermographicInspectionRecordEntity>) {
        if (powerStation != null) {
            val lastName = powerStation.code?.split("-")?.lastOrNull() ?: ""
            if (condition == ConditionType.NORMAL) {
                val filteredRecords = anomalyRecords.filter {
                    it.plantId == powerStation.id &&
                    it.condition == ConditionType.NORMAL
                }
                val newName = if (filteredRecords.isNotEmpty()) {
                    "THERMAL_RECORD_${filteredRecords.size + 1}_$lastName"
                } else {
                    "THERMAL_RECORD_1_$lastName"
                }
                _uiState.update { it.copy(recordName = newName) }
            }
        }
    }

    private fun handleRoiSelected(roi: com.tech.thermography.android.data.local.entity.ROIEntity) {
        _uiState.update { state ->
            val updatedThermogram = state.thermogram?.copy(
                selectedRoiId = roi.id,
                maxTempRoi = roi.maxTemp
            )
            state.copy(
                selectedRoi = roi,
                thermogram = updatedThermogram
            )
        }
    }

    private fun handleRefRoiSelected(roi: com.tech.thermography.android.data.local.entity.ROIEntity) {
        _uiState.update { state ->
            val updatedThermogramRef = state.thermogramRef?.copy(
                selectedRoiId = roi.id,
                maxTempRoi = roi.maxTemp
            )
            state.copy(
                selectedRefRoi = roi,
                thermogramRef = updatedThermogramRef
            )
        }
    }

    // Converte URI para path absoluto (/storage/...) ou mantém string para content://
    private fun Uri.toLocalPath(): String = when (scheme) {
        "file" -> path ?: toString()
        else   -> toString()
    }

    private fun handleImageSelected(uri: Uri) {
        _uiState.update { it.copy(thermogramImageUri = uri) }

        viewModelScope.launch {
            try {
                val result = flirReader.readMetadata(uri, context)
                result.onSuccess { metadata ->
                    val currentUserId = resolveCurrentUserId()
                    val equipmentId = _uiState.value.selectedEquipment?.id ?: UUID.randomUUID()

                    val realImageRef = _uiState.value.realImageUri?.toLocalPath() ?: ""
                    val localPath = uri.toLocalPath()

                    // 1. Criar Thermogram de Monitoramento
                    val thermogramId = UUID.randomUUID()
                    val thermogramMonitoring = metadata.toEntity(
                        id = thermogramId,
                        equipmentId = equipmentId,
                        createdById = currentUserId,
                        localImagePath = localPath,
                        localImageRefPath = realImageRef
                    )

                    // 2. Criar Thermogram de Referência (Cópia do metadado)
                    val thermogramRefId = UUID.randomUUID()
                    val thermogramReference = metadata.toEntity(
                        id = thermogramRefId,
                        equipmentId = equipmentId,
                        createdById = currentUserId,
                        localImagePath = localPath,
                        localImageRefPath = realImageRef
                    )

                    // 3. Criar ROIs para Monitoramento (cada ROI tem um novo ID e aponta para thermogramId)
                    val roisMonitoring = metadata.rois.map { 
                        it.toEntity(thermogramId).copy(id = UUID.randomUUID()) 
                    }

                    // 4. Criar ROIs para Referência (cada ROI tem um novo ID e aponta para thermogramRefId)
                    val roisReference = metadata.rois.map { 
                        it.toEntity(thermogramRefId).copy(id = UUID.randomUUID()) 
                    }

                    // SP1 (Sp1) é o primeiro ROI para monitoramento
                    // SP2 (Sp2) é o segundo ROI para referência (só se houver 2+ ROIs)
                    val selectedRoi = roisMonitoring.firstOrNull()
                    val hasMultipleRois = roisMonitoring.size > 1
                    val selectedRefRoi = if (hasMultipleRois) roisReference.getOrNull(1) else null

                    _uiState.update {
                        it.copy(
                            thermogram = thermogramMonitoring.copy(
                                selectedRoiId = selectedRoi?.id,
                                maxTempRoi = selectedRoi?.maxTemp
                            ),
                            thermogramRois = roisMonitoring,
                            selectedRoi = selectedRoi,

                            // Só preenche referência automaticamente se tiver mais de 1 ROI
                            thermogramRef = if (hasMultipleRois) thermogramReference.copy(
                                selectedRoiId = selectedRefRoi?.id,
                                maxTempRoi = selectedRefRoi?.maxTemp
                            ) else it.thermogramRef,
                            thermogramRefRois = if (hasMultipleRois) roisReference else it.thermogramRefRois,
                            selectedRefRoi = if (hasMultipleRois) selectedRefRoi else it.selectedRefRoi
                        )
                    }
                    _uiState.update { it.copy(thermogramError = null) }
                }
                result.onFailure { error ->
                    _uiState.update {
                        it.copy(thermogramError = "Aviso: Não foi possível ler metadados da imagem: ${error.message}")
                    }
                }
            } catch (e: Exception) {
                _uiState.update { it.copy(thermogramError = "Erro ao processar imagem: ${e.message}") }
            }
        }
    }

    private fun handleRefImageSelected(uri: Uri) {
        _uiState.update { it.copy(thermogramRefImageUri = uri) }
        viewModelScope.launch {
            try {
                val result = flirReader.readMetadata(uri, context)
                result.onSuccess { metadata ->
                    val currentUserId = resolveCurrentUserId()
                    val equipmentId = _uiState.value.selectedEquipment?.id ?: UUID.randomUUID()
                    val realImageRef = _uiState.value.realImageUri?.toLocalPath() ?: ""
                    val localPath = uri.toLocalPath()

                    val thermogramRefId = _uiState.value.thermogramRef?.id ?: UUID.randomUUID()
                    val thermogramReference = metadata.toEntity(
                        id = thermogramRefId,
                        equipmentId = equipmentId,
                        createdById = currentUserId,
                        localImagePath = localPath,
                        localImageRefPath = realImageRef
                    )

                    val roisReference = metadata.rois.map { 
                        it.toEntity(thermogramRefId).copy(id = UUID.randomUUID()) 
                    }

                    val selectedRefRoi = roisReference.firstOrNull()

                    _uiState.update {
                        it.copy(
                            thermogramRef = thermogramReference.copy(
                                selectedRoiId = selectedRefRoi?.id,
                                maxTempRoi = selectedRefRoi?.maxTemp
                            ),
                            thermogramRefRois = roisReference,
                            selectedRefRoi = selectedRefRoi,
                            thermogramRefError = null
                        )
                    }
                }
                result.onFailure { error ->
                    _uiState.update {
                        it.copy(thermogramRefError = "Aviso: Não foi possível ler metadados da imagem: ${error.message}")
                    }
                }
            } catch (e: Exception) {
                _uiState.update { it.copy(thermogramRefError = "Erro ao processar imagem: ${e.message}") }
            }
        }
    }

    private fun handleRealImageSelected(uri: android.net.Uri) {
        // Copia a imagem selecionada para a pasta app-specific Pictures/thermalEnergy e atualiza o estado
        viewModelScope.launch {
            try {
                val destDir = java.io.File(context.getExternalFilesDir(android.os.Environment.DIRECTORY_PICTURES), "thermalEnergy")
                if (!destDir.exists()) destDir.mkdirs()
                val destFile = java.io.File(destDir, "thermogram_${UUID.randomUUID()}.jpg")

                context.contentResolver.openInputStream(uri)?.use { input ->
                    destFile.outputStream().use { output ->
                        input.copyTo(output)
                    }
                }

                // Atualiza o MediaStore para garantir que o arquivo seja visível via galeria (opcional)
                try {
                    android.media.MediaScannerConnection.scanFile(context, arrayOf(destFile.absolutePath), null, null)
                } catch (_: Exception) {}

                val destUri = destFile.toUri()
                android.util.Log.d("ThermAnomVM", "Real image saved to: ${destFile.absolutePath}")

                _uiState.update { state ->
                    val path = destFile.absolutePath
                    state.copy(
                        realImageUri = destUri,
                        thermogram = state.thermogram?.copy(localImageRefPath = path),
                        thermogramRef = state.thermogramRef?.copy(localImageRefPath = path)
                    )
                }
            } catch (e: Exception) {
                // Em caso de erro, faz fallback para gravar a Uri original (não deve acontecer normalmente)
                android.util.Log.w("ThermAnomVM", "Failed to copy real image to app folder: ${e.message}")
                _uiState.update { state ->
                    val path = uri.toString()
                    state.copy(
                        realImageUri = uri,
                        thermogram = state.thermogram?.copy(localImageRefPath = path),
                        thermogramRef = state.thermogramRef?.copy(localImageRefPath = path)
                    )
                }
            }
        }
    }

    private fun updateAnalysisAndRecommendations() {
        val equipment = _uiState.value.selectedEquipment
        val component = _uiState.value.selectedComponent
        val condition = _uiState.value.condition

        if (equipment == null || component == null) {
            _uiState.update { it.copy(recommendations = "", analysisDescription = "") }
            return
        }

        viewModelScope.launch {
            val allDeadlines = riskRepo.getAllRiskPeriodicityDeadlines().first()
            val match = allDeadlines.find { it.name == condition.name }
            if (match != null) {
                val equipmentCode = equipment.code?.takeIf { it.isNotBlank() }
                val equipmentName = equipment.name
                val componentName = component.name
                val equipmentLabel = if (equipmentCode != null) "$equipmentCode ($equipmentName)" else equipmentName
                val analysisDescription = (match.description ?: "")
                    .replace("@COMPONENT", "\"$componentName\"")
                    .replace("@EQUIPMENT", "\"$equipmentLabel\"")
                _uiState.update {
                    it.copy(
                        recommendations = match.recommendations ?: "",
                        analysisDescription = analysisDescription
                    )
                }
            }
        }
    }

    fun calculateTemperatureDifference(): Double? {
        val objectTemp = _uiState.value.selectedRoi?.maxTemp
        val referenceTemp = _uiState.value.selectedRefRoi?.maxTemp ?: _uiState.value.thermogram?.reflectedTemp

        if (objectTemp == null || referenceTemp == null) return null
        return objectTemp - referenceTemp
    }

    private fun getRisk(value: Double, condition: String?): Boolean {
        if (condition.isNullOrBlank()) return false
        val lower = condition.lowercase().trim()
        if (lower == "não aplicável" || lower == "na") return false

        val parts = condition.split(" ")
        for (part in parts) {
            val regex = Regex("(<=|>=|<|>|=|≤|≥)(\\d+(\\.\\d+)?)")
            val match = regex.find(part)
            if (match == null) continue
            val operator = match.groupValues[1]
            val limit = match.groupValues[2].toDoubleOrNull() ?: continue

            when (operator) {
                "<", "<=" , "≤" -> if (!(value < limit || operator == "<=" && value <= limit || operator == "≤" && value <= limit)) return false
                ">", ">=" , "≥" -> if (!(value > limit || operator == ">=" && value >= limit || operator == "≥" && value >= limit)) return false
                "=" -> if (!(value == limit)) return false
            }
        }
        return true
    }

    private fun classifyRisk(value: Double?, limits: com.tech.thermography.android.data.local.entity.EquipmentComponentTemperatureLimitsEntity?): ConditionType {
        if (value == null || limits == null) return ConditionType.NORMAL
        return when {
            getRisk(value, limits.imminentHighRisk) -> ConditionType.IMMINENT_HIGH_RISK
            getRisk(value, limits.highRisk) -> ConditionType.HIGH_RISK
            getRisk(value, limits.mediumRisk) -> ConditionType.MEDIUM_RISK
            getRisk(value, limits.lowRisk) -> ConditionType.LOW_RISK
            getRisk(value, limits.normal) -> ConditionType.NORMAL
            else -> ConditionType.NORMAL
        }
    }

    private fun handleComponentSelected(component: com.tech.thermography.android.data.local.entity.EquipmentComponentEntity) {
        viewModelScope.launch {
            _uiState.update { it.copy(selectedComponent = component) }
            // Recalcula condição com base nos novos limites e deltaT
            val deltaT = calculateTemperatureDifference()
            val limits = limitsRepository.getEquipmentComponentTemperatureLimitsByComponentId(component.id)
            val newCondition = classifyRisk(deltaT, limits)
            _uiState.update { it.copy(condition = newCondition) }
            applyRiskPeriodicity(newCondition)
            // Atualiza recomendações e description depois que a condição foi determinada
            updateAnalysisAndRecommendations()
        }
    }

    private suspend fun getPeriodicityForCondition(condition: ConditionType): RiskPeriodicityDeadlineEntity? {
        val all = riskRepo.getAllRiskPeriodicityDeadlines().first()
        fun normalize(s: String?): String = s?.lowercase()?.replace("[^a-z0-9]".toRegex(), "") ?: ""
        val target = normalize(condition.name)
        return all.find { normalize(it.name) == target }
    }

    private suspend fun applyRiskPeriodicity(condition: ConditionType) {
        try {
            val match = getPeriodicityForCondition(condition)
            if (match != null) {
                val rec = match.recommendations ?: ""
                val deadlineMillis: Long? = if (match.deadline == null || match.deadline < 0 || match.deadlineUnit == null) {
                    null
                } else {
                    val nowZ = ZonedDateTime.now(ZoneId.systemDefault())
                    val amount = match.deadline.toLong()
                    val unit = when (match.deadlineUnit) {
                        DatetimeUnit.HOUR -> ChronoUnit.HOURS
                        DatetimeUnit.DAY -> ChronoUnit.DAYS
                        DatetimeUnit.WEEK -> ChronoUnit.WEEKS
                        DatetimeUnit.MONTH -> ChronoUnit.MONTHS
                        DatetimeUnit.YEAR -> ChronoUnit.YEARS
                    }
                    nowZ.plus(amount, unit).toInstant().toEpochMilli()
                }
                val nextMonitoringMillis: Long? = if (match.periodicity == null || match.periodicity < 0 || match.periodicityUnit == null) {
                    null
                } else {
                    val nowZ = ZonedDateTime.now(ZoneId.systemDefault())
                    val amount = match.periodicity.toLong()
                    val unit = when (match.periodicityUnit) {
                        DatetimeUnit.HOUR -> ChronoUnit.HOURS
                        DatetimeUnit.DAY -> ChronoUnit.DAYS
                        DatetimeUnit.WEEK -> ChronoUnit.WEEKS
                        DatetimeUnit.MONTH -> ChronoUnit.MONTHS
                        DatetimeUnit.YEAR -> ChronoUnit.YEARS
                    }
                    nowZ.plus(amount, unit).toInstant().toEpochMilli()
                }
                _uiState.update { it.copy(recommendations = rec, deadlineExecution = deadlineMillis, nextMonitoring = nextMonitoringMillis) }
            } else {
                _uiState.update { it.copy(recommendations = "", deadlineExecution = null) }
            }
        } catch (e: Exception) {
            _uiState.update { it.copy(error = "Erro ao carregar periodicidade: ${e.message}") }
        }
    }

    private suspend fun resolveCurrentUserId(): UUID {
        try {
            val token = sessionStore.token.first()
            if (!token.isNullOrBlank()) {
                val parts = token.split('.')
                if (parts.size >= 2) {
                    val payload = parts[1]
                    val decodedBytes = Base64.decode(payload, Base64.URL_SAFE or Base64.NO_PADDING or Base64.NO_WRAP)
                    val payloadJson = String(decodedBytes)
                    val jo = JSONObject(payloadJson)
                    val candidates = listOf("sub", "user_id", "userId", "id")
                    for (k in candidates) {
                        if (jo.has(k)) {
                            val v = jo.optString(k).takeIf { it.isNotBlank() }
                            if (!v.isNullOrBlank()) {
                                try { return UUID.fromString(v) } catch (_: Exception) {}
                            }
                        }
                    }
                }
            }
        } catch (e: Exception) {
            Log.w("ThermAnomVM", "Failed to parse token for user id: ${e.message}")
        }

        val users = userInfoRepository.getAllUserInfos().first()
        val first = users.firstOrNull()
        if (first != null) return first.id

        val defaultUser = com.tech.thermography.android.data.local.entity.UserInfoEntity(
            id = UUID.randomUUID(),
            position = "Local User",
            phoneNumber = null,
            companyId = null
        )
        userInfoRepository.insertUserInfo(defaultUser)
        return defaultUser.id
    }
}

package com.tech.thermography.android.flir

import android.app.Activity
import android.graphics.Bitmap
import android.graphics.Rect
import android.os.Build
import android.os.Handler
import android.os.Looper
import android.view.PixelCopy
import com.flir.thermalsdk.image.ThermalImage
import com.flir.thermalsdk.log.ThermalLog
import java.io.File
import java.nio.ByteBuffer
import java.util.concurrent.CountDownLatch
import java.util.concurrent.TimeUnit
import javax.inject.Inject

/**
 * Captures the entire screen (GL + Compose UI) and saves it as a FLIR overlay.
 * Uses PixelCopy API (Android 8.0+) to capture the window surface.
 */
class SnapshotManager @Inject constructor() {

    companion object {
        private const val TAG = "SnapshotManager"
    }

    interface Callback {
        fun onSuccess(file: File)
        fun onError(error: String, exception: Throwable? = null)
    }

    /**
     * Captures the ENTIRE SCREEN (GL thermal + Compose UI) synchronously and returns a JavaImageBuffer for overlay.
     * This combines: GL framebuffer (thermal stream) + Compose UI (toolbar, temperature bar, Bx1/delta).
     * 
     * Strategy:
     * 1. Capture GL framebuffer with glReadPixels (thermal background)
     * 2. Capture Compose UI with PixelCopy (overlay elements)
     * 3. Composite both images (thermal as background + UI on top)
     * 
     * This method MUST be called from the GL thread while ThermalImage is still valid.
     * 
     * @param activity The activity whose window will be captured
     * @param width GL surface width
     * @param height GL surface height
     * @return JavaImageBuffer with the complete composite (thermal + UI), or null if failed
     */
    fun captureGLFramebufferAsOverlay(activity: Activity, width: Int, height: Int): com.flir.thermalsdk.image.JavaImageBuffer? {
        if (width <= 0 || height <= 0) {
            ThermalLog.e(TAG, "Invalid surface size: ${width}x$height")
            return null
        }

        try {
            ThermalLog.d(TAG, "Capturing composite: GL thermal (${width}x$height) + Compose UI")

            // ===== STEP 1: Capture GL framebuffer (thermal stream) =====
            ThermalLog.d(TAG, "Step 1: Capturing GL framebuffer (thermal)...")
            val thermalBitmap = captureGLFramebuffer(width, height)
            if (thermalBitmap == null) {
                ThermalLog.e(TAG, "Failed to capture GL framebuffer")
                return null
            }

            // ===== STEP 2: Capture Compose UI with PixelCopy =====
            ThermalLog.d(TAG, "Step 2: Capturing Compose UI with PixelCopy...")
            val uiBitmap = captureComposeUI(activity, width, height)

            // ===== STEP 3: Composite both images =====
            ThermalLog.d(TAG, "Step 3: Compositing thermal + UI...")
            val compositeBitmap = if (uiBitmap != null) {
                // Composite: thermal background + UI overlay
                compositeBitmaps(thermalBitmap, uiBitmap)
            } else {
                // Fallback: use only thermal if UI capture failed
                ThermalLog.w(TAG, "UI capture failed, using only thermal")
                thermalBitmap
            }

            // ===== DEBUG: Save composite to verify =====
//            try {
//                val debugFile = File(
//                    android.os.Environment.getExternalStoragePublicDirectory(android.os.Environment.DIRECTORY_PICTURES),
//                    "debug_composite_${System.currentTimeMillis()}.jpg"
//                )
//                debugFile.outputStream().use { out ->
//                    compositeBitmap.compress(Bitmap.CompressFormat.JPEG, 95, out)
//                }
//                ThermalLog.i(TAG, " DEBUG: Composite saved to: ${debugFile.absolutePath}")
//                ThermalLog.i(TAG, " DEBUG: Should show thermal + toolbar + temperature bar + Bx1 + delta")
//            } catch (e: Exception) {
//                ThermalLog.w(TAG, "Failed to save debug composite: ${e.message}")
//            }
            // ===== END DEBUG =====

            // ===== STEP 4: Convert to JavaImageBuffer =====
            val imageSize = compositeBitmap.byteCount
            val rawBuffer = ByteBuffer.allocate(imageSize)
            compositeBitmap.copyPixelsToBuffer(rawBuffer)
            rawBuffer.rewind()

            val overlay = createJavaImageBuffer(rawBuffer, compositeBitmap.width, compositeBitmap.height)

            // Clean up bitmaps
            compositeBitmap.recycle()
            if (uiBitmap != null && uiBitmap != compositeBitmap) {
                uiBitmap.recycle()
            }

            if (overlay != null) {
                ThermalLog.i(TAG, "✓ Composite (thermal + UI) created as JavaImageBuffer")
            } else {
                ThermalLog.e(TAG, "❌ Failed to create JavaImageBuffer from composite")
            }

            return overlay

        } catch (e: Exception) {
            ThermalLog.e(TAG, "Failed to capture composite: ${e.message}")
            e.printStackTrace()
            return null
        }
    }

    /**
     * Capture GL framebuffer (thermal stream) using glReadPixels.
     * Returns thermal image as Bitmap.
     */
    private fun captureGLFramebuffer(width: Int, height: Int): Bitmap? {
        try {
            // Ensure all GL commands are finished
            android.opengl.GLES20.glFinish()
            android.opengl.GLES20.glPixelStorei(android.opengl.GLES20.GL_PACK_ALIGNMENT, 1)

            // Allocate buffer for RGBA data
            val pixelCount = width * height
            val byteCount = pixelCount * 4
            val glReadBuffer = ByteBuffer.allocate(byteCount)

            // Read pixels from GL framebuffer
            android.opengl.GLES20.glReadPixels(
                0, 0, width, height,
                android.opengl.GLES20.GL_RGBA,
                android.opengl.GLES20.GL_UNSIGNED_BYTE,
                glReadBuffer
            )
            glReadBuffer.rewind()

            // Convert RGBA → ARGB
            val argbPixels = IntArray(pixelCount)
            convertRGBAtoARGB(glReadBuffer, argbPixels, width, height)

            // Flip vertical (GL renders upside-down)
            flipVertical(argbPixels, width, height)

            // Create Bitmap
            val bitmap = Bitmap.createBitmap(width, height, Bitmap.Config.ARGB_8888)
            bitmap.setPixels(argbPixels, 0, width, 0, 0, width, height)

            ThermalLog.d(TAG, "GL framebuffer captured: ${width}x${height}")
            return bitmap

        } catch (e: Exception) {
            ThermalLog.e(TAG, "Failed to capture GL framebuffer: ${e.message}")
            return null
        }
    }

    /**
     * Capture Compose UI using PixelCopy (synchronously).
     * Returns UI elements as Bitmap, or null if failed.
     */
    private fun captureComposeUI(activity: Activity, targetWidth: Int, targetHeight: Int): Bitmap? {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.O) {
            ThermalLog.w(TAG, "PixelCopy requires Android 8.0+, skipping UI capture")
            return null
        }

        try {
            val window = activity.window
            val decorView = window.decorView

            val captureWidth = decorView.width
            val captureHeight = decorView.height

            if (captureWidth <= 0 || captureHeight <= 0) {
                ThermalLog.w(TAG, "Invalid window size: ${captureWidth}x${captureHeight}")
                return null
            }

            // Create bitmap
            val bitmap = Bitmap.createBitmap(captureWidth, captureHeight, Bitmap.Config.ARGB_8888)

            // Use CountDownLatch for synchronous operation
            val latch = CountDownLatch(1)
            var pixelCopyResult = -1

            // Post to Main thread
            Handler(Looper.getMainLooper()).post {
                try {
                    PixelCopy.request(
                        window,
                        Rect(0, 0, captureWidth, captureHeight),
                        bitmap,
                        { result ->
                            pixelCopyResult = result
                            latch.countDown()
                        },
                        Handler(Looper.getMainLooper())
                    )
                } catch (e: Exception) {
                    ThermalLog.e(TAG, "PixelCopy request failed: ${e.message}")
                    latch.countDown()
                }
            }

            // Wait for completion
            val timeout = latch.await(2, TimeUnit.SECONDS)

            if (!timeout || pixelCopyResult != PixelCopy.SUCCESS) {
                bitmap.recycle()
                ThermalLog.w(TAG, "PixelCopy failed or timeout, skipping UI")
                return null
            }

            // Resize UI bitmap to match thermal bitmap size for correct compositing alignment
            val finalBitmap = if (captureWidth != targetWidth || captureHeight != targetHeight) {
                ThermalLog.d(TAG, "Resizing UI bitmap from ${captureWidth}x${captureHeight} to ${targetWidth}x${targetHeight}")
                Bitmap.createScaledBitmap(bitmap, targetWidth, targetHeight, true).also {
                    bitmap.recycle()
                }
            } else {
                bitmap
            }
            ThermalLog.d(TAG, "Compose UI captured: ${finalBitmap.width}x${finalBitmap.height}")
            return finalBitmap

        } catch (e: Exception) {
            ThermalLog.e(TAG, "Failed to capture Compose UI: ${e.message}")
            return null
        }
    }

    /**
     * Composite two bitmaps: thermal as background + UI on top.
     * UI pixels with low alpha are treated as transparent (to show thermal underneath).
     */
    private fun compositeBitmaps(thermalBitmap: Bitmap, uiBitmap: Bitmap): Bitmap {
        val width = thermalBitmap.width
        val height = thermalBitmap.height

        // Create result bitmap
        val result = Bitmap.createBitmap(width, height, Bitmap.Config.ARGB_8888)
        val canvas = android.graphics.Canvas(result)

        // Draw thermal as background
        canvas.drawBitmap(thermalBitmap, 0f, 0f, null)

        // Draw UI on top (will composite automatically based on alpha)
        val paint = android.graphics.Paint()
        canvas.drawBitmap(uiBitmap, 0f, 0f, paint)

        ThermalLog.d(TAG, "Composited thermal + UI: ${width}x${height}")
        return result
    }

    /**
     * Convert RGBA buffer to ARGB int array.
     */
    private fun convertRGBAtoARGB(buffer: ByteBuffer, outPixels: IntArray, width: Int, height: Int) {
        val pixelCount = width * height
        for (i in 0 until pixelCount) {
            val r = buffer.get().toInt() and 0xFF
            val g = buffer.get().toInt() and 0xFF
            val b = buffer.get().toInt() and 0xFF
            val a = buffer.get().toInt() and 0xFF
            outPixels[i] = (a shl 24) or (r shl 16) or (g shl 8) or b
        }
    }

    /**
     * Flip image vertically (GL renders upside-down).
     */
    private fun flipVertical(pixels: IntArray, width: Int, height: Int) {
        val temp = IntArray(width)
        for (y in 0 until height / 2) {
            val topOffset = y * width
            val bottomOffset = (height - 1 - y) * width

            // Swap rows
            System.arraycopy(pixels, topOffset, temp, 0, width)
            System.arraycopy(pixels, bottomOffset, pixels, topOffset, width)
            System.arraycopy(temp, 0, pixels, bottomOffset, width)
        }
    }

    /**
     * [DEPRECATED - NOT USED ANYMORE]
     * Captures the full screen and saves it alongside the ThermalImage.
     * Use captureGLFramebufferAsOverlay() instead for synchronous capture.
     */
    @Deprecated("Use captureGLFramebufferAsOverlay() instead", ReplaceWith("captureGLFramebufferAsOverlay(width, height)"))
    fun captureAndSave(
        activity: Activity,
        thermalImage: ThermalImage,
        file: File,
        thermalWidth: Int? = null,
        thermalHeight: Int? = null,
        callback: Callback
    ) {
        // Validate API level
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.O) {
            callback.onError("PixelCopy requires Android 8.0 (API 26) or higher. Current: ${Build.VERSION.SDK_INT}")
            return
        }

        val window = activity.window
        val decorView = window.decorView

        if (decorView.width == 0 || decorView.height == 0) {
            callback.onError("View not ready for capture (width=${decorView.width}, height=${decorView.height})")
            return
        }

        ThermalLog.d(TAG, "Starting screen capture: ${decorView.width}x${decorView.height}")

        val bitmap = Bitmap.createBitmap(
            decorView.width,
            decorView.height,
            Bitmap.Config.ARGB_8888
        )

        try {
            PixelCopy.request(
                window,
                Rect(0, 0, decorView.width, decorView.height),
                bitmap,
                { result ->
                    handlePixelCopyResult(
                        result,
                        bitmap,
                        thermalImage,
                        file,
                        thermalWidth,
                        thermalHeight,
                        callback
                    )
                },
                Handler(Looper.getMainLooper())
            )
        } catch (e: Exception) {
            bitmap.recycle()
            ThermalLog.e(TAG, "PixelCopy request failed: ${e.message}")
            callback.onError("Failed to execute PixelCopy", e)
        }
    }

    /**
     * [DEPRECATED - NOT USED ANYMORE]
     * This method saves overlay as SEPARATE PNG file which creates 2 files total.
     * Use captureGLFramebufferAsOverlay() instead which creates 1 file with embedded overlay.
     */
    @Deprecated("Creates 2 files. Use captureGLFramebufferAsOverlay() instead", ReplaceWith("captureGLFramebufferAsOverlay(width, height)"))
    fun captureAndAddOverlay(
        activity: Activity,
        thermalFile: File,
        thermalWidth: Int? = null,
        thermalHeight: Int? = null,
        callback: Callback
    ) {
        // Validate API level
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.O) {
            callback.onError("PixelCopy requires Android 8.0 (API 26) or higher. Current: ${Build.VERSION.SDK_INT}")
            return
        }

        val window = activity.window
        val decorView = window.decorView

        if (decorView.width == 0 || decorView.height == 0) {
            callback.onError("View not ready for capture (width=${decorView.width}, height=${decorView.height})")
            return
        }

        ThermalLog.d(TAG, "Starting screen capture to add overlay: ${decorView.width}x${decorView.height}")

        val bitmap = Bitmap.createBitmap(
            decorView.width,
            decorView.height,
            Bitmap.Config.ARGB_8888
        )

        try {
            PixelCopy.request(
                window,
                Rect(0, 0, decorView.width, decorView.height),
                bitmap,
                { result ->
                    handlePixelCopyForOverlay(
                        result,
                        bitmap,
                        thermalFile,
                        thermalWidth,
                        thermalHeight,
                        callback
                    )
                },
                Handler(Looper.getMainLooper())
            )
        } catch (e: Exception) {
            bitmap.recycle()
            ThermalLog.e(TAG, "PixelCopy request failed: ${e.message}")
            callback.onError("Failed to execute PixelCopy", e)
        }
    }

    private fun handlePixelCopyResult(
        result: Int,
        bitmap: Bitmap,
        thermalImage: ThermalImage,
        file: File,
        thermalWidth: Int?,
        thermalHeight: Int?,
        callback: Callback
    ) {
        if (result != PixelCopy.SUCCESS) {
            bitmap.recycle()
            val errorMsg = when (result) {
                PixelCopy.ERROR_DESTINATION_INVALID -> "Destination bitmap invalid"
                PixelCopy.ERROR_SOURCE_INVALID -> "Source window invalid"
                PixelCopy.ERROR_SOURCE_NO_DATA -> "Source has no data"
                PixelCopy.ERROR_TIMEOUT -> "Capture timeout"
                else -> "Unknown error code: $result"
            }
            ThermalLog.e(TAG, "PixelCopy failed: $errorMsg")
            callback.onError("PixelCopy failed: $errorMsg")
            return
        }

        ThermalLog.d(TAG, "PixelCopy successful, processing overlay...")

        var finalBitmap: Bitmap? = null
        try {
            // Resize if needed to match thermal resolution
            finalBitmap = resizeIfNeeded(bitmap, thermalWidth, thermalHeight)

            ThermalLog.d(TAG, "Creating JavaImageBuffer from ${finalBitmap.width}x${finalBitmap.height} bitmap")

            // Convert to ByteBuffer (heap-based as per FLIR docs)
            val buffer = bitmapToByteBuffer(finalBitmap)

            // Try to create JavaImageBuffer with multiple strategies
            val overlay = createJavaImageBuffer(buffer, finalBitmap.width, finalBitmap.height)
                ?: throw IllegalStateException("Failed to create JavaImageBuffer")

            ThermalLog.d(TAG, "Saving thermal image with overlay to: ${file.absolutePath}")
            thermalImage.saveAs(file.absolutePath, overlay)

            ThermalLog.i(TAG, "✓ Snapshot with overlay saved successfully")
            callback.onSuccess(file)

        } catch (e: Exception) {
            ThermalLog.e(TAG, "Failed to save snapshot with overlay: ${e.message}")
            callback.onError("Failed to save snapshot with overlay", e)
        } finally {
            // Clean up bitmaps to avoid memory leaks
            if (finalBitmap != bitmap) {
                finalBitmap?.recycle()
            }
            bitmap.recycle()
        }
    }

    /**
     * Handle PixelCopy result for saving overlay as separate PNG file.
     * Since ThermalImage.fromFile() doesn't exist and the ThermalImage reference
     * is already invalid at this point, we save the overlay as a separate file.
     */
    private fun handlePixelCopyForOverlay(
        result: Int,
        bitmap: Bitmap,
        thermalFile: File,
        thermalWidth: Int?,
        thermalHeight: Int?,
        callback: Callback
    ) {
        if (result != PixelCopy.SUCCESS) {
            bitmap.recycle()
            val errorMsg = when (result) {
                PixelCopy.ERROR_DESTINATION_INVALID -> "Destination bitmap invalid"
                PixelCopy.ERROR_SOURCE_INVALID -> "Source window invalid"
                PixelCopy.ERROR_SOURCE_NO_DATA -> "Source has no data"
                PixelCopy.ERROR_TIMEOUT -> "Capture timeout"
                else -> "Unknown error code: $result"
            }
            ThermalLog.e(TAG, "PixelCopy failed: $errorMsg")
            callback.onError("PixelCopy failed: $errorMsg")
            return
        }

        ThermalLog.d(TAG, "PixelCopy successful, saving overlay as separate PNG file...")

        var finalBitmap: Bitmap? = null
        try {
            // Resize if needed to match thermal resolution
            finalBitmap = resizeIfNeeded(bitmap, thermalWidth, thermalHeight)

            // Create overlay file path (same name with _overlay.png suffix)
            val overlayFile = File(
                thermalFile.parentFile,
                thermalFile.nameWithoutExtension + "_overlay.png"
            )

            ThermalLog.d(TAG, "Saving overlay to: ${overlayFile.absolutePath}")

            // Save overlay as PNG (high quality, lossless)
            overlayFile.outputStream().use { out ->
                finalBitmap.compress(Bitmap.CompressFormat.PNG, 100, out)
            }

            ThermalLog.i(TAG, "✓ Snapshot saved successfully!")
            ThermalLog.i(TAG, "  - Thermal data: ${thermalFile.absolutePath}")
            ThermalLog.i(TAG, "  - Visual overlay: ${overlayFile.absolutePath}")

            // Return the thermal file (main file)
            callback.onSuccess(thermalFile)

        } catch (e: Exception) {
            ThermalLog.e(TAG, "Failed to save overlay file: ${e.message}")
            e.printStackTrace()
            callback.onError("Failed to save overlay file", e)
        } finally {
            // Clean up bitmaps to avoid memory leaks
            if (finalBitmap != bitmap) {
                finalBitmap?.recycle()
            }
            bitmap.recycle()
        }
    }

    /**
     * Resize bitmap to match thermal resolution if specified.
     */
    private fun resizeIfNeeded(
        bitmap: Bitmap,
        targetWidth: Int?,
        targetHeight: Int?
    ): Bitmap {
        if (targetWidth == null || targetHeight == null) {
            ThermalLog.d(TAG, "No resize needed (target dimensions not specified)")
            return bitmap
        }

        if (bitmap.width == targetWidth && bitmap.height == targetHeight) {
            ThermalLog.d(TAG, "No resize needed (dimensions already match)")
            return bitmap
        }

        ThermalLog.d(TAG, "Resizing from ${bitmap.width}x${bitmap.height} to ${targetWidth}x${targetHeight}")
        return Bitmap.createScaledBitmap(bitmap, targetWidth, targetHeight, true)
    }

    /**
     * Convert Bitmap → ByteBuffer (heap-based).
     * Uses allocate() instead of allocateDirect() as per FLIR SDK documentation.
     */
    private fun bitmapToByteBuffer(bitmap: Bitmap): ByteBuffer {
        val size = bitmap.byteCount
        val buffer = ByteBuffer.allocate(size)
        bitmap.copyPixelsToBuffer(buffer)
        buffer.rewind()
        ThermalLog.d(TAG, "Converted bitmap to ByteBuffer: $size bytes")
        return buffer
    }

    /**
     * Create JavaImageBuffer using reflection to support different SDK versions.
     * Tries multiple constructor signatures in order of preference.
     */
    private fun createJavaImageBuffer(buffer: ByteBuffer, width: Int, height: Int): com.flir.thermalsdk.image.JavaImageBuffer? {
        val pixelData = buffer.array()

        // Strategy 0: Try the REAL constructor signature found in the SDK
        // JavaImageBuffer(byte[], Format, int, int, int)
        val formatEnum = findFormatEnum()
        if (formatEnum != null) {
            val stride = width * 4  // ARGB8888 = 4 bytes per pixel

            tryDeclaredConstructor(
                listOf(ByteArray::class.java, formatEnum.javaClass, Int::class.javaPrimitiveType!!, Int::class.javaPrimitiveType!!, Int::class.javaPrimitiveType!!),
                listOf(pixelData, formatEnum, width, height, stride)
            )?.let {
                ThermalLog.i(TAG, "✓ Created JavaImageBuffer with Constructor(byte[], Format, int, int, int)")
                return it
            }
        }

        // Strategy 1: Try BitmapAndroid wrapper
        tryBitmapAndroid(pixelData, width, height)?.let {
            ThermalLog.i(TAG, "✓ Created JavaImageBuffer via BitmapAndroid")
            return it
        }

        // Strategy 2: Try Builder pattern
        tryBuilder(pixelData, width, height)?.let {
            ThermalLog.i(TAG, "✓ Created JavaImageBuffer via Builder")
            return it
        }

        // Strategy 3: Try other constructor variations (legacy support)
        if (formatEnum != null) {
            // Try: JavaImageBuffer(ByteBuffer, int, int, Format)
            tryConstructor(
                listOf(ByteBuffer::class.java, Int::class.javaPrimitiveType!!, Int::class.javaPrimitiveType!!, formatEnum.javaClass),
                listOf(ByteBuffer.wrap(pixelData), width, height, formatEnum)
            )?.let { 
                ThermalLog.i(TAG, "✓ Created JavaImageBuffer with Constructor(ByteBuffer, int, int, Format)")
                return it 
            }

            // Try: JavaImageBuffer(byte[], int, int, Format)
            tryConstructor(
                listOf(ByteArray::class.java, Int::class.javaPrimitiveType!!, Int::class.javaPrimitiveType!!, formatEnum.javaClass),
                listOf(pixelData, width, height, formatEnum)
            )?.let {
                ThermalLog.i(TAG, "✓ Created JavaImageBuffer with Constructor(byte[], int, int, Format)")
                return it
            }
        }

        // Strategy 4: Try without format
        tryConstructor(
            listOf(ByteBuffer::class.java, Int::class.javaPrimitiveType!!, Int::class.javaPrimitiveType!!),
            listOf(ByteBuffer.wrap(pixelData), width, height)
        )?.let {
            ThermalLog.i(TAG, "✓ Created JavaImageBuffer with Constructor(ByteBuffer, int, int)")
            return it
        }

        tryConstructor(
            listOf(ByteArray::class.java, Int::class.javaPrimitiveType!!, Int::class.javaPrimitiveType!!),
            listOf(pixelData, width, height)
        )?.let {
            ThermalLog.i(TAG, "✓ Created JavaImageBuffer with Constructor(byte[], int, int)")
            return it
        }

        ThermalLog.e(TAG, "❌ No compatible JavaImageBuffer constructor found")
        logAvailableConstructors()
        return null
    }

    /**
     * Try to use declared constructor (including package-private/protected).
     * This is needed because JavaImageBuffer has no public constructors.
     */
    private fun tryDeclaredConstructor(paramTypes: List<Class<*>>, paramValues: List<Any>): com.flir.thermalsdk.image.JavaImageBuffer? {
        try {
            val constructor = com.flir.thermalsdk.image.JavaImageBuffer::class.java.getDeclaredConstructor(*paramTypes.toTypedArray())
            constructor.isAccessible = true  // ← CRITICAL: Acessa construtor não-público!
            val result = constructor.newInstance(*paramValues.toTypedArray())
            ThermalLog.d(TAG, "Successfully invoked declared constructor")
            return result as com.flir.thermalsdk.image.JavaImageBuffer
        } catch (e: NoSuchMethodException) {
            ThermalLog.w(TAG, "Declared constructor not found: ${paramTypes.joinToString { it.simpleName }}")
            return null
        } catch (e: java.lang.reflect.InvocationTargetException) {
            ThermalLog.e(TAG, "Declared constructor invocation failed: ${e.cause?.message ?: e.message}")
            e.cause?.printStackTrace()
            return null
        } catch (e: Exception) {
            ThermalLog.w(TAG, "Declared constructor attempt failed: ${e.javaClass.simpleName}: ${e.message}")
            e.printStackTrace()
            return null
        }
    }

    /**
     * Try to create JavaImageBuffer via BitmapAndroid wrapper.
     */
    private fun tryBitmapAndroid(pixelData: ByteArray, width: Int, height: Int): com.flir.thermalsdk.image.JavaImageBuffer? {
        try {
            // Create bitmap from pixel data
            val bitmap = Bitmap.createBitmap(width, height, Bitmap.Config.ARGB_8888)
            val buffer = ByteBuffer.wrap(pixelData)
            buffer.rewind()
            bitmap.copyPixelsFromBuffer(buffer)

            // Try to create BitmapAndroid
            val bitmapAndroidClass = Class.forName("com.flir.thermalsdk.androidsdk.image.BitmapAndroid")
            val bitmapAndroid = bitmapAndroidClass.getConstructor(Bitmap::class.java).newInstance(bitmap)

            // Check if it's a JavaImageBuffer
            if (bitmapAndroid is com.flir.thermalsdk.image.JavaImageBuffer) {
                return bitmapAndroid
            }

            // Try to extract JavaImageBuffer from it
            try {
                val method = bitmapAndroidClass.getMethod("getImageBuffer")
                val result = method.invoke(bitmapAndroid)
                if (result is com.flir.thermalsdk.image.JavaImageBuffer) {
                    return result
                }
            } catch (e: Exception) {
                ThermalLog.w(TAG, "BitmapAndroid.getImageBuffer() failed: ${e.message}")
            }

            bitmap.recycle()
        } catch (e: ClassNotFoundException) {
            ThermalLog.w(TAG, "BitmapAndroid class not found")
        } catch (e: Exception) {
            ThermalLog.w(TAG, "BitmapAndroid approach failed: ${e.message}")
        }
        return null
    }

    /**
     * Try to create JavaImageBuffer via Builder pattern.
     */
    private fun tryBuilder(pixelData: ByteArray, width: Int, height: Int): com.flir.thermalsdk.image.JavaImageBuffer? {
        try {
            val builderClass = Class.forName("com.flir.thermalsdk.image.JavaImageBuffer\$Builder")
            val builder = builderClass.getDeclaredConstructor().newInstance()

            var anySet = false

            // Try to set dimensions
            anySet = tryInvoke(builder, "width", width) || anySet
            anySet = tryInvoke(builder, "setWidth", width) || anySet
            anySet = tryInvoke(builder, "height", height) || anySet
            anySet = tryInvoke(builder, "setHeight", height) || anySet

            // Try to set format
            val formatEnum = findFormatEnum()
            if (formatEnum != null) {
                anySet = tryInvoke(builder, "format", formatEnum) || anySet
                anySet = tryInvoke(builder, "setFormat", formatEnum) || anySet
            }

            // Try to set pixel data
            anySet = tryInvoke(builder, "pixels", pixelData) || anySet
            anySet = tryInvoke(builder, "setPixels", pixelData) || anySet
            anySet = tryInvoke(builder, "buffer", ByteBuffer.wrap(pixelData)) || anySet
            anySet = tryInvoke(builder, "setBuffer", ByteBuffer.wrap(pixelData)) || anySet
            anySet = tryInvoke(builder, "data", pixelData) || anySet
            anySet = tryInvoke(builder, "setData", pixelData) || anySet

            if (!anySet) {
                ThermalLog.w(TAG, "Builder exists but no setters worked")
                return null
            }

            // Try to build
            val buildMethod = builderClass.getMethod("build")
            val result = buildMethod.invoke(builder)

            if (result is com.flir.thermalsdk.image.JavaImageBuffer) {
                return result
            } else {
                ThermalLog.w(TAG, "Builder.build() returned wrong type: ${result?.javaClass?.name ?: "null"}")
            }
        } catch (e: ClassNotFoundException) {
            ThermalLog.w(TAG, "Builder class not found")
        } catch (e: Exception) {
            ThermalLog.w(TAG, "Builder approach failed: ${e.message}")
        }
        return null
    }

    /**
     * Try to invoke a method on an object.
     */
    private fun tryInvoke(target: Any, methodName: String, arg: Any): Boolean {
        try {
            // Try with exact type
            val method = target.javaClass.getMethod(methodName, arg.javaClass)
            method.invoke(target, arg)
            return true
        } catch (e: NoSuchMethodException) {
            // Try with primitive int if arg is Integer
            if (arg is Int) {
                try {
                    val method = target.javaClass.getMethod(methodName, Int::class.javaPrimitiveType)
                    method.invoke(target, arg)
                    return true
                } catch (e2: Exception) {
                    // Ignore
                }
            }
        } catch (e: Exception) {
            // Ignore
        }
        return false
    }

    private fun tryConstructor(paramTypes: List<Class<*>>, paramValues: List<Any>): com.flir.thermalsdk.image.JavaImageBuffer? {
        try {
            val constructor = com.flir.thermalsdk.image.JavaImageBuffer::class.java.getConstructor(*paramTypes.toTypedArray())
            val result = constructor.newInstance(*paramValues.toTypedArray())
            return result as com.flir.thermalsdk.image.JavaImageBuffer
        } catch (e: NoSuchMethodException) {
            ThermalLog.w(TAG, "Constructor not found: ${paramTypes.joinToString { it.simpleName }}")
            return null
        } catch (e: java.lang.reflect.InvocationTargetException) {
            ThermalLog.w(TAG, "Constructor invocation failed: ${e.cause?.message ?: e.message}")
            e.cause?.printStackTrace()
            return null
        } catch (e: Exception) {
            ThermalLog.w(TAG, "Constructor attempt failed: ${e.javaClass.simpleName}: ${e.message}")
            e.printStackTrace()
            return null
        }
    }

    /**
     * Find the Format enum for ARGB8888 pixel format.
     */
    private fun findFormatEnum(): Any? {
        val enumClassNames = listOf(
            "com.flir.thermalsdk.image.JavaImageBuffer\$Format",
            "com.flir.thermalsdk.image.ImageBuffer\$Format",
            "com.flir.thermalsdk.image.JavaImageBufferType",
            "com.flir.thermalsdk.image.PixelFormat",
            "com.flir.thermalsdk.image.Format"
        )

        for (className in enumClassNames) {
            try {
                val enumClass = Class.forName(className)
                if (!enumClass.isEnum) continue

                val values = enumClass.enumConstants ?: continue

                // Try to find ARGB8888 or similar
                for (value in values) {
                    val name = (value as Enum<*>).name
                    if (name.contains("ARGB") && name.contains("8888")) {
                        ThermalLog.d(TAG, "Found format enum: $className.$name")
                        return value
                    }
                }

                // Fallback: use first value
                if (values.isNotEmpty()) {
                    ThermalLog.d(TAG, "Using first format enum: $className.${(values[0] as Enum<*>).name}")
                    return values[0]
                }
            } catch (e: Exception) {
                // Try next class name
            }
        }

        ThermalLog.w(TAG, "Could not find format enum")
        return null
    }

    /**
     * Log all available constructors for debugging.
     */
    private fun logAvailableConstructors() {
        try {
            ThermalLog.e(TAG, "Available JavaImageBuffer constructors:")
            val constructors = com.flir.thermalsdk.image.JavaImageBuffer::class.java.constructors

            if (constructors.isEmpty()) {
                ThermalLog.e(TAG, "  - (no public constructors found)")
            } else {
                for (ctor in constructors) {
                    val params = ctor.parameterTypes.joinToString(", ") { it.simpleName }
                    ThermalLog.e(TAG, "  - JavaImageBuffer($params)")
                }
            }

            // Also try declared constructors (including private/protected)
            ThermalLog.e(TAG, "All declared constructors (including private):")
            val declaredCtors = com.flir.thermalsdk.image.JavaImageBuffer::class.java.declaredConstructors
            for (ctor in declaredCtors) {
                val params = ctor.parameterTypes.joinToString(", ") { it.simpleName }
                val modifiers = java.lang.reflect.Modifier.toString(ctor.modifiers)
                ThermalLog.e(TAG, "  - $modifiers JavaImageBuffer($params)")
            }
        } catch (e: Exception) {
            ThermalLog.e(TAG, "Failed to list constructors: ${e.message}")
        }
    }
}

package com.tech.thermography.android.flir

import android.app.Activity
import android.graphics.Bitmap
import android.graphics.Rect
import android.os.Build
import android.os.Handler
import android.os.Looper
import android.view.PixelCopy
import com.flir.thermalsdk.image.ThermalImage
import com.flir.thermalsdk.log.ThermalLog
import java.io.File
import java.nio.ByteBuffer
import java.util.concurrent.CountDownLatch
import java.util.concurrent.TimeUnit
import javax.inject.Inject

/**
 * Captures the entire screen (GL + Compose UI) and saves it as a FLIR overlay.
 * Uses PixelCopy API (Android 8.0+) to capture the window surface.
 */
class SnapshotManager @Inject constructor() {

    companion object {
        private const val TAG = "SnapshotManager"
    }

    interface Callback {
        fun onSuccess(file: File)
        fun onError(error: String, exception: Throwable? = null)
    }

    /**
     * Captures the ENTIRE SCREEN (GL thermal + Compose UI) synchronously and returns a JavaImageBuffer for overlay.
     * This combines: GL framebuffer (thermal stream) + Compose UI (toolbar, temperature bar, Bx1/delta).
     * 
     * Strategy:
     * 1. Capture GL framebuffer with glReadPixels (thermal background)
     * 2. Capture Compose UI with PixelCopy (overlay elements)
     * 3. Composite both images (thermal as background + UI on top)
     * 
     * This method MUST be called from the GL thread while ThermalImage is still valid.
     * 
     * @param activity The activity whose window will be captured
     * @param width GL surface width
     * @param height GL surface height
     * @return JavaImageBuffer with the complete composite (thermal + UI), or null if failed
     */
    fun captureGLFramebufferAsOverlay(activity: Activity, width: Int, height: Int): com.flir.thermalsdk.image.JavaImageBuffer? {
        if (width <= 0 || height <= 0) {
            ThermalLog.e(TAG, "Invalid surface size: ${width}x$height")
            return null
        }

        try {
            ThermalLog.d(TAG, "Capturing composite: GL thermal (${width}x$height) + Compose UI")

            // ===== STEP 1: Capture GL framebuffer (thermal stream) =====
            ThermalLog.d(TAG, "Step 1: Capturing GL framebuffer (thermal)...")
            val thermalBitmap = captureGLFramebuffer(width, height)
            if (thermalBitmap == null) {
                ThermalLog.e(TAG, "Failed to capture GL framebuffer")
                return null
            }

            // ===== STEP 2: Capture Compose UI with PixelCopy =====
            ThermalLog.d(TAG, "Step 2: Capturing Compose UI with PixelCopy...")
            val uiBitmap = captureComposeUI(activity, width, height)

            // ===== STEP 3: Composite both images =====
            ThermalLog.d(TAG, "Step 3: Compositing thermal + UI...")
            val compositeBitmap = if (uiBitmap != null) {
                // Composite: thermal background + UI overlay
                compositeBitmaps(thermalBitmap, uiBitmap)
            } else {
                // Fallback: use only thermal if UI capture failed
                ThermalLog.w(TAG, "UI capture failed, using only thermal")
                thermalBitmap
            }

            // ===== DEBUG: Save composite to verify =====
//            try {
//                val debugFile = File(
//                    android.os.Environment.getExternalStoragePublicDirectory(android.os.Environment.DIRECTORY_PICTURES),
//                    "debug_composite_${System.currentTimeMillis()}.jpg"
//                )
//                debugFile.outputStream().use { out ->
//                    compositeBitmap.compress(Bitmap.CompressFormat.JPEG, 95, out)
//                }
//                ThermalLog.i(TAG, " DEBUG: Composite saved to: ${debugFile.absolutePath}")
//                ThermalLog.i(TAG, " DEBUG: Should show thermal + toolbar + temperature bar + Bx1 + delta")
//            } catch (e: Exception) {
//                ThermalLog.w(TAG, "Failed to save debug composite: ${e.message}")
//            }
            // ===== END DEBUG =====

            // ===== STEP 4: Convert to JavaImageBuffer =====
            val imageSize = compositeBitmap.byteCount
            val rawBuffer = ByteBuffer.allocate(imageSize)
            compositeBitmap.copyPixelsToBuffer(rawBuffer)
            rawBuffer.rewind()

            val overlay = createJavaImageBuffer(rawBuffer, compositeBitmap.width, compositeBitmap.height)

            // Clean up bitmaps
            compositeBitmap.recycle()
            if (uiBitmap != null && uiBitmap != compositeBitmap) {
                uiBitmap.recycle()
            }

            if (overlay != null) {
                ThermalLog.i(TAG, "✓ Composite (thermal + UI) created as JavaImageBuffer")
            } else {
                ThermalLog.e(TAG, "❌ Failed to create JavaImageBuffer from composite")
            }

            return overlay

        } catch (e: Exception) {
            ThermalLog.e(TAG, "Failed to capture composite: ${e.message}")
            e.printStackTrace()
            return null
        }
    }

    /**
     * Capture GL framebuffer (thermal stream) using glReadPixels.
     * Returns thermal image as Bitmap.
     */
    private fun captureGLFramebuffer(width: Int, height: Int): Bitmap? {
        try {
            // Ensure all GL commands are finished
            android.opengl.GLES20.glFinish()
            android.opengl.GLES20.glPixelStorei(android.opengl.GLES20.GL_PACK_ALIGNMENT, 1)

            // Allocate buffer for RGBA data
            val pixelCount = width * height
            val byteCount = pixelCount * 4
            val glReadBuffer = ByteBuffer.allocate(byteCount)

            // Read pixels from GL framebuffer
            android.opengl.GLES20.glReadPixels(
                0, 0, width, height,
                android.opengl.GLES20.GL_RGBA,
                android.opengl.GLES20.GL_UNSIGNED_BYTE,
                glReadBuffer
            )
            glReadBuffer.rewind()

            // Convert RGBA → ARGB
            val argbPixels = IntArray(pixelCount)
            convertRGBAtoARGB(glReadBuffer, argbPixels, width, height)

            // Flip vertical (GL renders upside-down)
            flipVertical(argbPixels, width, height)

            // Create Bitmap
            val bitmap = Bitmap.createBitmap(width, height, Bitmap.Config.ARGB_8888)
            bitmap.setPixels(argbPixels, 0, width, 0, 0, width, height)

            ThermalLog.d(TAG, "GL framebuffer captured: ${width}x${height}")
            return bitmap

        } catch (e: Exception) {
            ThermalLog.e(TAG, "Failed to capture GL framebuffer: ${e.message}")
            return null
        }
    }

    /**
     * Capture Compose UI using PixelCopy (synchronously).
     * Only captures the thermal area (top portion of the window = targetHeight rows),
     * excluding the toolbar and recent-images strip at the bottom.
     * Returns UI elements as Bitmap, or null if failed.
     */
    private fun captureComposeUI(activity: Activity, targetWidth: Int, targetHeight: Int): Bitmap? {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.O) {
            ThermalLog.w(TAG, "PixelCopy requires Android 8.0+, skipping UI capture")
            return null
        }

        try {
            val window = activity.window
            val decorView = window.decorView

            val windowWidth  = decorView.width
            val windowHeight = decorView.height

            if (windowWidth <= 0 || windowHeight <= 0) {
                ThermalLog.w(TAG, "Invalid window size: ${windowWidth}x${windowHeight}")
                return null
            }

            // Determine the Y offset where the thermal area starts (below the system status bar).
            val statusBarHeight: Int = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.R) {
                decorView.rootWindowInsets
                    ?.getInsets(android.view.WindowInsets.Type.statusBars())?.top ?: 0
            } else {
                @Suppress("DEPRECATION")
                decorView.rootWindowInsets?.systemWindowInsetTop ?: 0
            }

            // Source rect = only the thermal area (skip status bar on top; skip toolbar+recent below).
            val srcTop    = statusBarHeight
            val srcBottom = (statusBarHeight + targetHeight).coerceAtMost(windowHeight)
            val srcRect   = Rect(0, srcTop, windowWidth, srcBottom)

            ThermalLog.d(TAG, "PixelCopy srcRect=$srcRect window=${windowWidth}x${windowHeight} statusBar=$statusBarHeight")

            // Bitmap height = cropped thermal height
            val bitmap = Bitmap.createBitmap(windowWidth, srcBottom - srcTop, Bitmap.Config.ARGB_8888)

            val latch = CountDownLatch(1)
            var pixelCopyResult = -1

            Handler(Looper.getMainLooper()).post {
                try {
                    PixelCopy.request(
                        window,
                        srcRect,
                        bitmap,
                        { result ->
                            pixelCopyResult = result
                            latch.countDown()
                        },
                        Handler(Looper.getMainLooper())
                    )
                } catch (e: Exception) {
                    ThermalLog.e(TAG, "PixelCopy request failed: ${e.message}")
                    latch.countDown()
                }
            }

            val timeout = latch.await(2, TimeUnit.SECONDS)

            if (!timeout || pixelCopyResult != PixelCopy.SUCCESS) {
                bitmap.recycle()
                ThermalLog.w(TAG, "PixelCopy failed or timeout (result=$pixelCopyResult), skipping UI")
                return null
            }

            // Scale only if dimensions differ from the GL surface size
            val finalBitmap = if (bitmap.width != targetWidth || bitmap.height != targetHeight) {
                ThermalLog.d(TAG, "Scaling UI bitmap from ${bitmap.width}x${bitmap.height} to ${targetWidth}x${targetHeight}")
                Bitmap.createScaledBitmap(bitmap, targetWidth, targetHeight, true).also {
                    bitmap.recycle()
                }
            } else {
                bitmap
            }
            ThermalLog.d(TAG, "Compose UI captured (thermal area only): ${finalBitmap.width}x${finalBitmap.height}")
            return finalBitmap

        } catch (e: Exception) {
            ThermalLog.e(TAG, "Failed to capture Compose UI: ${e.message}")
            return null
        }
    }

    /**
     * Composite two bitmaps: thermal as background + UI on top.
     * UI pixels with low alpha are treated as transparent (to show thermal underneath).
     */
    private fun compositeBitmaps(thermalBitmap: Bitmap, uiBitmap: Bitmap): Bitmap {
        val width = thermalBitmap.width
        val height = thermalBitmap.height

        // Create result bitmap
        val result = Bitmap.createBitmap(width, height, Bitmap.Config.ARGB_8888)
        val canvas = android.graphics.Canvas(result)

        // Draw thermal as background
        canvas.drawBitmap(thermalBitmap, 0f, 0f, null)

        // Draw UI on top (will composite automatically based on alpha)
        val paint = android.graphics.Paint()
        canvas.drawBitmap(uiBitmap, 0f, 0f, paint)

        ThermalLog.d(TAG, "Composited thermal + UI: ${width}x${height}")
        return result
    }

    /**
     * Convert RGBA buffer to ARGB int array.
     */
    private fun convertRGBAtoARGB(buffer: ByteBuffer, outPixels: IntArray, width: Int, height: Int) {
        val pixelCount = width * height
        for (i in 0 until pixelCount) {
            val r = buffer.get().toInt() and 0xFF
            val g = buffer.get().toInt() and 0xFF
            val b = buffer.get().toInt() and 0xFF
            val a = buffer.get().toInt() and 0xFF
            outPixels[i] = (a shl 24) or (r shl 16) or (g shl 8) or b
        }
    }

    /**
     * Flip image vertically (GL renders upside-down).
     */
    private fun flipVertical(pixels: IntArray, width: Int, height: Int) {
        val temp = IntArray(width)
        for (y in 0 until height / 2) {
            val topOffset = y * width
            val bottomOffset = (height - 1 - y) * width

            // Swap rows
            System.arraycopy(pixels, topOffset, temp, 0, width)
            System.arraycopy(pixels, bottomOffset, pixels, topOffset, width)
            System.arraycopy(temp, 0, pixels, bottomOffset, width)
        }
    }

    /**
     * [DEPRECATED - NOT USED ANYMORE]
     * Captures the full screen and saves it alongside the ThermalImage.
     * Use captureGLFramebufferAsOverlay() instead for synchronous capture.
     */
    @Deprecated("Use captureGLFramebufferAsOverlay() instead", ReplaceWith("captureGLFramebufferAsOverlay(width, height)"))
    fun captureAndSave(
        activity: Activity,
        thermalImage: ThermalImage,
        file: File,
        thermalWidth: Int? = null,
        thermalHeight: Int? = null,
        callback: Callback
    ) {
        // Validate API level
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.O) {
            callback.onError("PixelCopy requires Android 8.0 (API 26) or higher. Current: ${Build.VERSION.SDK_INT}")
            return
        }

        val window = activity.window
        val decorView = window.decorView

        if (decorView.width == 0 || decorView.height == 0) {
            callback.onError("View not ready for capture (width=${decorView.width}, height=${decorView.height})")
            return
        }

        ThermalLog.d(TAG, "Starting screen capture: ${decorView.width}x${decorView.height}")

        val bitmap = Bitmap.createBitmap(
            decorView.width,
            decorView.height,
            Bitmap.Config.ARGB_8888
        )

        try {
            PixelCopy.request(
                window,
                Rect(0, 0, decorView.width, decorView.height),
                bitmap,
                { result ->
                    handlePixelCopyResult(
                        result,
                        bitmap,
                        thermalImage,
                        file,
                        thermalWidth,
                        thermalHeight,
                        callback
                    )
                },
                Handler(Looper.getMainLooper())
            )
        } catch (e: Exception) {
            bitmap.recycle()
            ThermalLog.e(TAG, "PixelCopy request failed: ${e.message}")
            callback.onError("Failed to execute PixelCopy", e)
        }
    }

    /**
     * [DEPRECATED - NOT USED ANYMORE]
     * This method saves overlay as SEPARATE PNG file which creates 2 files total.
     * Use captureGLFramebufferAsOverlay() instead which creates 1 file with embedded overlay.
     */
    @Deprecated("Creates 2 files. Use captureGLFramebufferAsOverlay() instead", ReplaceWith("captureGLFramebufferAsOverlay(width, height)"))
    fun captureAndAddOverlay(
        activity: Activity,
        thermalFile: File,
        thermalWidth: Int? = null,
        thermalHeight: Int? = null,
        callback: Callback
    ) {
        // Validate API level
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.O) {
            callback.onError("PixelCopy requires Android 8.0 (API 26) or higher. Current: ${Build.VERSION.SDK_INT}")
            return
        }

        val window = activity.window
        val decorView = window.decorView

        if (decorView.width == 0 || decorView.height == 0) {
            callback.onError("View not ready for capture (width=${decorView.width}, height=${decorView.height})")
            return
        }

        ThermalLog.d(TAG, "Starting screen capture to add overlay: ${decorView.width}x${decorView.height}")

        val bitmap = Bitmap.createBitmap(
            decorView.width,
            decorView.height,
            Bitmap.Config.ARGB_8888
        )

        try {
            PixelCopy.request(
                window,
                Rect(0, 0, decorView.width, decorView.height),
                bitmap,
                { result ->
                    handlePixelCopyForOverlay(
                        result,
                        bitmap,
                        thermalFile,
                        thermalWidth,
                        thermalHeight,
                        callback
                    )
                },
                Handler(Looper.getMainLooper())
            )
        } catch (e: Exception) {
            bitmap.recycle()
            ThermalLog.e(TAG, "PixelCopy request failed: ${e.message}")
            callback.onError("Failed to execute PixelCopy", e)
        }
    }

    private fun handlePixelCopyResult(
        result: Int,
        bitmap: Bitmap,
        thermalImage: ThermalImage,
        file: File,
        thermalWidth: Int?,
        thermalHeight: Int?,
        callback: Callback
    ) {
        if (result != PixelCopy.SUCCESS) {
            bitmap.recycle()
            val errorMsg = when (result) {
                PixelCopy.ERROR_DESTINATION_INVALID -> "Destination bitmap invalid"
                PixelCopy.ERROR_SOURCE_INVALID -> "Source window invalid"
                PixelCopy.ERROR_SOURCE_NO_DATA -> "Source has no data"
                PixelCopy.ERROR_TIMEOUT -> "Capture timeout"
                else -> "Unknown error code: $result"
            }
            ThermalLog.e(TAG, "PixelCopy failed: $errorMsg")
            callback.onError("PixelCopy failed: $errorMsg")
            return
        }

        ThermalLog.d(TAG, "PixelCopy successful, processing overlay...")

        var finalBitmap: Bitmap? = null
        try {
            // Resize if needed to match thermal resolution
            finalBitmap = resizeIfNeeded(bitmap, thermalWidth, thermalHeight)

            ThermalLog.d(TAG, "Creating JavaImageBuffer from ${finalBitmap.width}x${finalBitmap.height} bitmap")

            // Convert to ByteBuffer (heap-based as per FLIR docs)
            val buffer = bitmapToByteBuffer(finalBitmap)

            // Try to create JavaImageBuffer with multiple strategies
            val overlay = createJavaImageBuffer(buffer, finalBitmap.width, finalBitmap.height)
                ?: throw IllegalStateException("Failed to create JavaImageBuffer")

            ThermalLog.d(TAG, "Saving thermal image with overlay to: ${file.absolutePath}")
            thermalImage.saveAs(file.absolutePath, overlay)

            ThermalLog.i(TAG, "✓ Snapshot with overlay saved successfully")
            callback.onSuccess(file)

        } catch (e: Exception) {
            ThermalLog.e(TAG, "Failed to save snapshot with overlay: ${e.message}")
            callback.onError("Failed to save snapshot with overlay", e)
        } finally {
            // Clean up bitmaps to avoid memory leaks
            if (finalBitmap != bitmap) {
                finalBitmap?.recycle()
            }
            bitmap.recycle()
        }
    }

    /**
     * Handle PixelCopy result for saving overlay as separate PNG file.
     * Since ThermalImage.fromFile() doesn't exist and the ThermalImage reference
     * is already invalid at this point, we save the overlay as a separate file.
     */
    private fun handlePixelCopyForOverlay(
        result: Int,
        bitmap: Bitmap,
        thermalFile: File,
        thermalWidth: Int?,
        thermalHeight: Int?,
        callback: Callback
    ) {
        if (result != PixelCopy.SUCCESS) {
            bitmap.recycle()
            val errorMsg = when (result) {
                PixelCopy.ERROR_DESTINATION_INVALID -> "Destination bitmap invalid"
                PixelCopy.ERROR_SOURCE_INVALID -> "Source window invalid"
                PixelCopy.ERROR_SOURCE_NO_DATA -> "Source has no data"
                PixelCopy.ERROR_TIMEOUT -> "Capture timeout"
                else -> "Unknown error code: $result"
            }
            ThermalLog.e(TAG, "PixelCopy failed: $errorMsg")
            callback.onError("PixelCopy failed: $errorMsg")
            return
        }

        ThermalLog.d(TAG, "PixelCopy successful, saving overlay as separate PNG file...")

        var finalBitmap: Bitmap? = null
        try {
            // Resize if needed to match thermal resolution
            finalBitmap = resizeIfNeeded(bitmap, thermalWidth, thermalHeight)

            // Create overlay file path (same name with _overlay.png suffix)
            val overlayFile = File(
                thermalFile.parentFile,
                thermalFile.nameWithoutExtension + "_overlay.png"
            )

            ThermalLog.d(TAG, "Saving overlay to: ${overlayFile.absolutePath}")

            // Save overlay as PNG (high quality, lossless)
            overlayFile.outputStream().use { out ->
                finalBitmap.compress(Bitmap.CompressFormat.PNG, 100, out)
            }

            ThermalLog.i(TAG, "✓ Snapshot saved successfully!")
            ThermalLog.i(TAG, "  - Thermal data: ${thermalFile.absolutePath}")
            ThermalLog.i(TAG, "  - Visual overlay: ${overlayFile.absolutePath}")

            // Return the thermal file (main file)
            callback.onSuccess(thermalFile)

        } catch (e: Exception) {
            ThermalLog.e(TAG, "Failed to save overlay file: ${e.message}")
            e.printStackTrace()
            callback.onError("Failed to save overlay file", e)
        } finally {
            // Clean up bitmaps to avoid memory leaks
            if (finalBitmap != bitmap) {
                finalBitmap?.recycle()
            }
            bitmap.recycle()
        }
    }

    /**
     * Resize bitmap to match thermal resolution if specified.
     */
    private fun resizeIfNeeded(
        bitmap: Bitmap,
        targetWidth: Int?,
        targetHeight: Int?
    ): Bitmap {
        if (targetWidth == null || targetHeight == null) {
            ThermalLog.d(TAG, "No resize needed (target dimensions not specified)")
            return bitmap
        }

        if (bitmap.width == targetWidth && bitmap.height == targetHeight) {
            ThermalLog.d(TAG, "No resize needed (dimensions already match)")
            return bitmap
        }

        ThermalLog.d(TAG, "Resizing from ${bitmap.width}x${bitmap.height} to ${targetWidth}x${targetHeight}")
        return Bitmap.createScaledBitmap(bitmap, targetWidth, targetHeight, true)
    }

    /**
     * Convert Bitmap → ByteBuffer (heap-based).
     * Uses allocate() instead of allocateDirect() as per FLIR SDK documentation.
     */
    private fun bitmapToByteBuffer(bitmap: Bitmap): ByteBuffer {
        val size = bitmap.byteCount
        val buffer = ByteBuffer.allocate(size)
        bitmap.copyPixelsToBuffer(buffer)
        buffer.rewind()
        ThermalLog.d(TAG, "Converted bitmap to ByteBuffer: $size bytes")
        return buffer
    }

    /**
     * Create JavaImageBuffer using reflection to support different SDK versions.
     * Tries multiple constructor signatures in order of preference.
     */
    private fun createJavaImageBuffer(buffer: ByteBuffer, width: Int, height: Int): com.flir.thermalsdk.image.JavaImageBuffer? {
        val pixelData = buffer.array()

        // Strategy 0: Try the REAL constructor signature found in the SDK
        // JavaImageBuffer(byte[], Format, int, int, int)
        val formatEnum = findFormatEnum()
        if (formatEnum != null) {
            val stride = width * 4  // ARGB8888 = 4 bytes per pixel

            tryDeclaredConstructor(
                listOf(ByteArray::class.java, formatEnum.javaClass, Int::class.javaPrimitiveType!!, Int::class.javaPrimitiveType!!, Int::class.javaPrimitiveType!!),
                listOf(pixelData, formatEnum, width, height, stride)
            )?.let {
                ThermalLog.i(TAG, "✓ Created JavaImageBuffer with Constructor(byte[], Format, int, int, int)")
                return it
            }
        }

        // Strategy 1: Try BitmapAndroid wrapper
        tryBitmapAndroid(pixelData, width, height)?.let {
            ThermalLog.i(TAG, "✓ Created JavaImageBuffer via BitmapAndroid")
            return it
        }

        // Strategy 2: Try Builder pattern
        tryBuilder(pixelData, width, height)?.let {
            ThermalLog.i(TAG, "✓ Created JavaImageBuffer via Builder")
            return it
        }

        // Strategy 3: Try other constructor variations (legacy support)
        if (formatEnum != null) {
            // Try: JavaImageBuffer(ByteBuffer, int, int, Format)
            tryConstructor(
                listOf(ByteBuffer::class.java, Int::class.javaPrimitiveType!!, Int::class.javaPrimitiveType!!, formatEnum.javaClass),
                listOf(ByteBuffer.wrap(pixelData), width, height, formatEnum)
            )?.let { 
                ThermalLog.i(TAG, "✓ Created JavaImageBuffer with Constructor(ByteBuffer, int, int, Format)")
                return it 
            }

            // Try: JavaImageBuffer(byte[], int, int, Format)
            tryConstructor(
                listOf(ByteArray::class.java, Int::class.javaPrimitiveType!!, Int::class.javaPrimitiveType!!, formatEnum.javaClass),
                listOf(pixelData, width, height, formatEnum)
            )?.let {
                ThermalLog.i(TAG, "✓ Created JavaImageBuffer with Constructor(byte[], int, int, Format)")
                return it
            }
        }

        // Strategy 4: Try without format
        tryConstructor(
            listOf(ByteBuffer::class.java, Int::class.javaPrimitiveType!!, Int::class.javaPrimitiveType!!),
            listOf(ByteBuffer.wrap(pixelData), width, height)
        )?.let {
            ThermalLog.i(TAG, "✓ Created JavaImageBuffer with Constructor(ByteBuffer, int, int)")
            return it
        }

        tryConstructor(
            listOf(ByteArray::class.java, Int::class.javaPrimitiveType!!, Int::class.javaPrimitiveType!!),
            listOf(pixelData, width, height)
        )?.let {
            ThermalLog.i(TAG, "✓ Created JavaImageBuffer with Constructor(byte[], int, int)")
            return it
        }

        ThermalLog.e(TAG, "❌ No compatible JavaImageBuffer constructor found")
        logAvailableConstructors()
        return null
    }

    /**
     * Try to use declared constructor (including package-private/protected).
     * This is needed because JavaImageBuffer has no public constructors.
     */
    private fun tryDeclaredConstructor(paramTypes: List<Class<*>>, paramValues: List<Any>): com.flir.thermalsdk.image.JavaImageBuffer? {
        try {
            val constructor = com.flir.thermalsdk.image.JavaImageBuffer::class.java.getDeclaredConstructor(*paramTypes.toTypedArray())
            constructor.isAccessible = true  // ← CRITICAL: Acessa construtor não-público!
            val result = constructor.newInstance(*paramValues.toTypedArray())
            ThermalLog.d(TAG, "Successfully invoked declared constructor")
            return result as com.flir.thermalsdk.image.JavaImageBuffer
        } catch (e: NoSuchMethodException) {
            ThermalLog.w(TAG, "Declared constructor not found: ${paramTypes.joinToString { it.simpleName }}")
            return null
        } catch (e: java.lang.reflect.InvocationTargetException) {
            ThermalLog.e(TAG, "Declared constructor invocation failed: ${e.cause?.message ?: e.message}")
            e.cause?.printStackTrace()
            return null
        } catch (e: Exception) {
            ThermalLog.w(TAG, "Declared constructor attempt failed: ${e.javaClass.simpleName}: ${e.message}")
            e.printStackTrace()
            return null
        }
    }

    /**
     * Try to create JavaImageBuffer via BitmapAndroid wrapper.
     */
    private fun tryBitmapAndroid(pixelData: ByteArray, width: Int, height: Int): com.flir.thermalsdk.image.JavaImageBuffer? {
        try {
            // Create bitmap from pixel data
            val bitmap = Bitmap.createBitmap(width, height, Bitmap.Config.ARGB_8888)
            val buffer = ByteBuffer.wrap(pixelData)
            buffer.rewind()
            bitmap.copyPixelsFromBuffer(buffer)

            // Try to create BitmapAndroid
            val bitmapAndroidClass = Class.forName("com.flir.thermalsdk.androidsdk.image.BitmapAndroid")
            val bitmapAndroid = bitmapAndroidClass.getConstructor(Bitmap::class.java).newInstance(bitmap)

            // Check if it's a JavaImageBuffer
            if (bitmapAndroid is com.flir.thermalsdk.image.JavaImageBuffer) {
                return bitmapAndroid
            }

            // Try to extract JavaImageBuffer from it
            try {
                val method = bitmapAndroidClass.getMethod("getImageBuffer")
                val result = method.invoke(bitmapAndroid)
                if (result is com.flir.thermalsdk.image.JavaImageBuffer) {
                    return result
                }
            } catch (e: Exception) {
                ThermalLog.w(TAG, "BitmapAndroid.getImageBuffer() failed: ${e.message}")
            }

            bitmap.recycle()
        } catch (e: ClassNotFoundException) {
            ThermalLog.w(TAG, "BitmapAndroid class not found")
        } catch (e: Exception) {
            ThermalLog.w(TAG, "BitmapAndroid approach failed: ${e.message}")
        }
        return null
    }

    /**
     * Try to create JavaImageBuffer via Builder pattern.
     */
    private fun tryBuilder(pixelData: ByteArray, width: Int, height: Int): com.flir.thermalsdk.image.JavaImageBuffer? {
        try {
            val builderClass = Class.forName("com.flir.thermalsdk.image.JavaImageBuffer\$Builder")
            val builder = builderClass.getDeclaredConstructor().newInstance()

            var anySet = false

            // Try to set dimensions
            anySet = tryInvoke(builder, "width", width) || anySet
            anySet = tryInvoke(builder, "setWidth", width) || anySet
            anySet = tryInvoke(builder, "height", height) || anySet
            anySet = tryInvoke(builder, "setHeight", height) || anySet

            // Try to set format
            val formatEnum = findFormatEnum()
            if (formatEnum != null) {
                anySet = tryInvoke(builder, "format", formatEnum) || anySet
                anySet = tryInvoke(builder, "setFormat", formatEnum) || anySet
            }

            // Try to set pixel data
            anySet = tryInvoke(builder, "pixels", pixelData) || anySet
            anySet = tryInvoke(builder, "setPixels", pixelData) || anySet
            anySet = tryInvoke(builder, "buffer", ByteBuffer.wrap(pixelData)) || anySet
            anySet = tryInvoke(builder, "setBuffer", ByteBuffer.wrap(pixelData)) || anySet
            anySet = tryInvoke(builder, "data", pixelData) || anySet
            anySet = tryInvoke(builder, "setData", pixelData) || anySet

            if (!anySet) {
                ThermalLog.w(TAG, "Builder exists but no setters worked")
                return null
            }

            // Try to build
            val buildMethod = builderClass.getMethod("build")
            val result = buildMethod.invoke(builder)

            if (result is com.flir.thermalsdk.image.JavaImageBuffer) {
                return result
            } else {
                ThermalLog.w(TAG, "Builder.build() returned wrong type: ${result?.javaClass?.name ?: "null"}")
            }
        } catch (e: ClassNotFoundException) {
            ThermalLog.w(TAG, "Builder class not found")
        } catch (e: Exception) {
            ThermalLog.w(TAG, "Builder approach failed: ${e.message}")
        }
        return null
    }

    /**
     * Try to invoke a method on an object.
     */
    private fun tryInvoke(target: Any, methodName: String, arg: Any): Boolean {
        try {
            // Try with exact type
            val method = target.javaClass.getMethod(methodName, arg.javaClass)
            method.invoke(target, arg)
            return true
        } catch (e: NoSuchMethodException) {
            // Try with primitive int if arg is Integer
            if (arg is Int) {
                try {
                    val method = target.javaClass.getMethod(methodName, Int::class.javaPrimitiveType)
                    method.invoke(target, arg)
                    return true
                } catch (e2: Exception) {
                    // Ignore
                }
            }
        } catch (e: Exception) {
            // Ignore
        }
        return false
    }

    private fun tryConstructor(paramTypes: List<Class<*>>, paramValues: List<Any>): com.flir.thermalsdk.image.JavaImageBuffer? {
        try {
            val constructor = com.flir.thermalsdk.image.JavaImageBuffer::class.java.getConstructor(*paramTypes.toTypedArray())
            val result = constructor.newInstance(*paramValues.toTypedArray())
            return result as com.flir.thermalsdk.image.JavaImageBuffer
        } catch (e: NoSuchMethodException) {
            ThermalLog.w(TAG, "Constructor not found: ${paramTypes.joinToString { it.simpleName }}")
            return null
        } catch (e: java.lang.reflect.InvocationTargetException) {
            ThermalLog.w(TAG, "Constructor invocation failed: ${e.cause?.message ?: e.message}")
            e.cause?.printStackTrace()
            return null
        } catch (e: Exception) {
            ThermalLog.w(TAG, "Constructor attempt failed: ${e.javaClass.simpleName}: ${e.message}")
            e.printStackTrace()
            return null
        }
    }

    /**
     * Find the Format enum for ARGB8888 pixel format.
     */
    private fun findFormatEnum(): Any? {
        val enumClassNames = listOf(
            "com.flir.thermalsdk.image.JavaImageBuffer\$Format",
            "com.flir.thermalsdk.image.ImageBuffer\$Format",
            "com.flir.thermalsdk.image.JavaImageBufferType",
            "com.flir.thermalsdk.image.PixelFormat",
            "com.flir.thermalsdk.image.Format"
        )

        for (className in enumClassNames) {
            try {
                val enumClass = Class.forName(className)
                if (!enumClass.isEnum) continue

                val values = enumClass.enumConstants ?: continue

                // Try to find ARGB8888 or similar
                for (value in values) {
                    val name = (value as Enum<*>).name
                    if (name.contains("ARGB") && name.contains("8888")) {
                        ThermalLog.d(TAG, "Found format enum: $className.$name")
                        return value
                    }
                }

                // Fallback: use first value
                if (values.isNotEmpty()) {
                    ThermalLog.d(TAG, "Using first format enum: $className.${(values[0] as Enum<*>).name}")
                    return values[0]
                }
            } catch (e: Exception) {
                // Try next class name
            }
        }

        ThermalLog.w(TAG, "Could not find format enum")
        return null
    }

    /**
     * Log all available constructors for debugging.
     */
    private fun logAvailableConstructors() {
        try {
            ThermalLog.e(TAG, "Available JavaImageBuffer constructors:")
            val constructors = com.flir.thermalsdk.image.JavaImageBuffer::class.java.constructors

            if (constructors.isEmpty()) {
                ThermalLog.e(TAG, "  - (no public constructors found)")
            } else {
                for (ctor in constructors) {
                    val params = ctor.parameterTypes.joinToString(", ") { it.simpleName }
                    ThermalLog.e(TAG, "  - JavaImageBuffer($params)")
                }
            }

            // Also try declared constructors (including private/protected)
            ThermalLog.e(TAG, "All declared constructors (including private):")
            val declaredCtors = com.flir.thermalsdk.image.JavaImageBuffer::class.java.declaredConstructors
            for (ctor in declaredCtors) {
                val params = ctor.parameterTypes.joinToString(", ") { it.simpleName }
                val modifiers = java.lang.reflect.Modifier.toString(ctor.modifiers)
                ThermalLog.e(TAG, "  - $modifiers JavaImageBuffer($params)")
            }
        } catch (e: Exception) {
            ThermalLog.e(TAG, "Failed to list constructors: ${e.message}")
        }
    }
}

package com.tech.thermography.android.ui.camera

import android.app.Activity
import android.content.Context
import android.opengl.GLSurfaceView
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.flir.thermalsdk.image.TemperatureUnit
import com.flir.thermalsdk.image.ThermalValue
import com.flir.thermalsdk.image.fusion.FusionMode
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.delay
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.isActive
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import org.json.JSONArray
import java.io.File
import javax.inject.Inject
import com.flir.thermalsdk.live.remote.StoredImage
import com.tech.thermography.android.flir.AceController
import com.tech.thermography.android.flir.AceController.TemperatureRange
import dagger.hilt.android.qualifiers.ApplicationContext
import dagger.hilt.android.lifecycle.HiltViewModel

@HiltViewModel
class ThermogramCameraViewModel @Inject constructor(
    private val controller: AceController,
    @ApplicationContext private val context: Context
) : ViewModel() {
    // Palettes disponíveis
    private val _palettes = MutableStateFlow<List<com.flir.thermalsdk.image.Palette>>(emptyList())
    val palettes: StateFlow<List<com.flir.thermalsdk.image.Palette>> = _palettes.asStateFlow()

    // Palette selecionada
    private val _currentPalette = MutableStateFlow<com.flir.thermalsdk.image.Palette?>(null)
    val currentPalette: StateFlow<com.flir.thermalsdk.image.Palette?> = _currentPalette.asStateFlow()

    // Modos de fusão disponíveis
    val fusionModesWithLabel = listOf(
        FusionMode.THERMAL_ONLY to "Térmica",
        FusionMode.MSX to "MSX",
        FusionMode.VISUAL_ONLY to "Câmera Digital"
    )

    private val _currentFusionMode = kotlinx.coroutines.flow.MutableStateFlow(FusionMode.THERMAL_ONLY)
    val currentFusionMode: kotlinx.coroutines.flow.StateFlow<FusionMode> = _currentFusionMode.asStateFlow()

    companion object {
        private const val PREFS_NAME = "recent_thermograms"
        private const val KEY_RECENT = "recent_paths"
        // Mapa de nomes de palette para labels amigáveis
        val PALETTE_LABELS = mapOf(
            "iron" to "Ferro",
            "lava" to "Lava",
            "rainbow" to "Arco-Íris",
            "rainhc" to "Elevado Contraste de Arco-Íris",
            "artic" to "Ártico",
            "whitehot" to "Incandescente Branco",
            "blackhot" to "Incandescente Preto"
        )
    }

    private val _recentThermograms = MutableStateFlow<List<String>>(emptyList())
    val recentThermograms: StateFlow<List<String>> = _recentThermograms.asStateFlow()

    // Lista reduzida de palettes com label amigável, ordenada conforme a ordem do mapa
    val filteredPalettesWithLabel: List<Pair<com.flir.thermalsdk.image.Palette, String>>
        get() {
            val paletteOrder = PALETTE_LABELS.keys.toList()
            val filtered = _palettes.value.mapNotNull { palette ->
                val nameKey = palette.name?.replace(" ", "")?.lowercase() ?: return@mapNotNull null
                val label = PALETTE_LABELS[nameKey]
                if (label != null) palette to label else null
            }
            // Ordena conforme a ordem do mapa
            return paletteOrder.flatMap { key ->
                filtered.filter { (palette, _) ->
                    palette.name?.replace(" ", "")?.lowercase() == key
                }
            }
        }


    //Atualização do estado de temperatura
    private val _measurementTemperatures = MutableStateFlow(MeasurementTemperatures())
    val measurementTemperatures: StateFlow<MeasurementTemperatures> = _measurementTemperatures.asStateFlow()

    //Atualização do range de temperatura
    private val _temperatureRange = MutableStateFlow(getTemperatureRange())
    val temperatureRange: StateFlow<TemperatureRange?> = _temperatureRange.asStateFlow()

    // Parâmetros térmicos UI
    data class ThermalParametersUi(
        val distance: Double = 1.0,
        val emissivity: Double = 0.95,
        val reflectedTemperature: ThermalValue = ThermalValue(20.0, TemperatureUnit.CELSIUS),
        val atmosphericTemperature: ThermalValue = ThermalValue(20.0, TemperatureUnit.CELSIUS),
        val relativeHumidity: Double = 50.0
    )

    private val _thermalParametersUi = MutableStateFlow(ThermalParametersUi())
    val thermalParametersUi: StateFlow<ThermalParametersUi> = _thermalParametersUi

    init {
        // Inicializa lista de palettes e seleciona a primeira como padrão
        val defaultPalettes = com.flir.thermalsdk.image.PaletteManager.getDefaultPalettes()
        _palettes.value = defaultPalettes
        _currentPalette.value = defaultPalettes.firstOrNull()
        _currentPalette.value?.let { controller.setCurrentPalette(it) }
        _recentThermograms.value = loadRecentThermograms().filter { File(it).exists() }
        persistRecentThermograms(_recentThermograms.value)

        startTemperaturesRangeUpdates()
        startMeasurementTemperaturesUpdates()

        // Inicializa modo de fusão padrão
        controller.setCurrentFusionMode(FusionMode.THERMAL_ONLY)
    }

    fun selectPalette(palette: com.flir.thermalsdk.image.Palette) {
        _currentPalette.value = palette
        controller.setCurrentPalette(palette)
    }

    fun selectFusionMode(mode: FusionMode) {
        _currentFusionMode.value = mode
        controller.setCurrentFusionMode(mode)
    }

    private fun startTemperaturesRangeUpdates() {
        viewModelScope.launch {
            while (isActive) {
                _temperatureRange.value = getTemperatureRange()
                delay(500)
            }
        }
    }

    private fun startMeasurementTemperaturesUpdates() {
        viewModelScope.launch {
            while (isActive) {
                _measurementTemperatures.value = getMeasurementTemperatures()!!
                delay(500)
            }
        }
    }

    fun attachGlSurface(glView: GLSurfaceView) {
        controller.attachSurface(glView)
    }

    fun onSurfaceSizeChanged(width: Int, height: Int) {
        controller.onSurfaceSizeChanged(width, height)
    }

    fun start() {
        controller.startCamera()
    }

    fun stop() {
        controller.disconnect()
    }

    override fun onCleared() {
        controller.disconnect()
    }


    /**
     * Requests the camera to store a snapshot WITH screen overlay (saved as separate PNG).
     * Creates 2 files: snapshot_XXX.jpg (thermal) + snapshot_XXX_overlay.png (UI)
     * The callback returns (success, message, storedImage?)
     */
    fun takeSnapshotWithOverlay(
        activity: Activity,
        callback: (Boolean, String?, StoredImage?) -> Unit = { _, _, _ -> }
    ) {
        controller.takeSnapshotWithOverlay(activity) { success, msg, storedImage ->
            if (success && !msg.isNullOrBlank()) {
                onSnapshotSaved(msg)
            }
            callback(success, msg, storedImage)
        }
    }

    fun onSnapshotSaved(path: String) {
        _recentThermograms.value = buildList {
            add(path)
            addAll(_recentThermograms.value.filterNot { it == path })
        }.filter { File(it).exists() }.take(20)
        persistRecentThermograms(_recentThermograms.value)
    }

    fun removeRecentThermogram(path: String, deleteFile: Boolean = true) {
        _recentThermograms.value = _recentThermograms.value.filterNot { it == path }
        persistRecentThermograms(_recentThermograms.value)

        if (deleteFile) {
            viewModelScope.launch(Dispatchers.IO) {
                runCatching { File(path).delete() }
            }
        }
    }

    fun pruneMissingRecentThermograms() {
        val filtered = _recentThermograms.value.filter { File(it).exists() }
        if (filtered != _recentThermograms.value) {
            _recentThermograms.value = filtered
            persistRecentThermograms(filtered)
        }
    }

    private fun persistRecentThermograms(paths: List<String>) {
        val payload = JSONArray().apply { paths.forEach { put(it) } }.toString()
        context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)
            .edit()
            .putString(KEY_RECENT, payload)
            .apply()
    }

    private fun loadRecentThermograms(): List<String> {
        val raw = context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)
            .getString(KEY_RECENT, null)
            ?: return emptyList()
        return runCatching {
            val array = JSONArray(raw)
            buildList {
                for (i in 0 until array.length()) {
                    val path = array.optString(i)
                    if (path.isNotBlank()) add(path)
                }
            }
        }.getOrElse { emptyList() }
    }

    fun toggleLaser(callback: (Boolean, String?) -> Unit = { _, _ -> }) {
        controller.toggleLaser(callback)
    }

    fun toggleFlash(callback: (Boolean, String?) -> Unit = { _, _ -> }) {
        controller.toggleLamp(callback)
    }

    fun getTemperatureRange(): AceController.TemperatureRange? {
        return controller.getTemperatureRange()
    }

    fun getMeasurementTemperatures(): MeasurementTemperatures? {
        return controller.getMeasurementTemperatures()
    }

    fun setMeasurementSquareStates(states: List<MeasurementState>) {
        controller.setMeasurementStates(states)
    }

    // Atualiza os parâmetros térmicos UI
    fun updateThermalParametersUi(update: (ThermalParametersUi) -> ThermalParametersUi) {
        _thermalParametersUi.value = update(_thermalParametersUi.value)
    }

    // Salva os parâmetros térmicos no controlador
    fun saveThermalParameters() {
        val params = _thermalParametersUi.value
        controller.setThermalParameters(
            distance = params.distance,
            emissivity = params.emissivity,
            reflectedTemperature = params.reflectedTemperature,
            atmosphericTemperature = params.atmosphericTemperature,
            relativeHumidity = params.relativeHumidity
        )
    }
}

